using Azure.Core;
using Azure.Identity;
using CareConnector.Infrastructure.Modules;
using CareConnector.Modules.Census.Contracts;
using CareConnector.Modules.Census.Endpoints;
using CareConnector.Modules.Census.ExternalCensus;
using CareConnector.Modules.Census.Persistence;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;

namespace CareConnector.Modules.Census;

/// <summary>Beds, stays, passes, AWOL, holds, and reconciliation with the census system of record.</summary>
public sealed class CensusModule : IModule
{
    public string Name => "Census";

    public Type DbContextType => typeof(CensusDbContext);

    public void AddServices(IServiceCollection services, IConfiguration configuration)
    {
        services.AddModuleDbContext<CensusDbContext>(configuration, CensusDbContext.SchemaName);
        services.AddScoped<ICensus, CensusReader>();
        services.AddScoped<IExternalResidentDirectory, ExternalResidentDirectory>();
        services.AddScoped<IResidentScopeDirectory, ResidentScopeDirectory>();
        services.AddScoped<CareConnector.SharedKernel.IWorkItemSource, CensusWorkItems>();
        services.AddScoped<CensusCommand>();
        services.AddMemoryCache();

        var section = configuration.GetSection(ExternalCensusOptions.SectionName);
        services.Configure<ExternalCensusOptions>(section);
        if (string.Equals(section["Source"], "AlamoPlatform", StringComparison.OrdinalIgnoreCase))
        {
            services.TryAddSingleton<TokenCredential>(_ => new DefaultAzureCredential());
            services.AddHttpClient<IExternalCensusSource, AlamoPlatformCensusSource>();
        }
        else
        {
            services.AddSingleton<IExternalCensusSource, SyntheticCensusSource>();
        }
    }

    public void MapEndpoints(IEndpointRouteBuilder endpoints)
    {
        CensusEndpoints.Map(endpoints);
        CensusReports.Map(endpoints);
    }
}

