using CareConnector.SharedKernel;

namespace CareConnector.Modules.Census.Domain;

internal enum BedStatus
{
    Available,
    Occupied,
    OutOfService,
}

internal sealed class Bed : AggregateRoot
{
    private Bed()
    {
    }

    /// <summary>The facility this bed belongs to (platform facility id).</summary>
    public string FacilityId { get; private set; } = FacilityDirectory.DefaultFacilityId;

    public string Unit { get; private set; } = "";

    public string Label { get; private set; } = "";

    public BedStatus Status { get; private set; }

    public Guid? OccupiedByStayId { get; private set; }

    public string? OutOfServiceReason { get; private set; }

    public string Display => $"{Unit} {Label}";

    public static Result<Bed> Create(string unit, string label, string? facilityId = null)
    {
        if (string.IsNullOrWhiteSpace(unit) || string.IsNullOrWhiteSpace(label))
        {
            return new Error("bed.name_required", "Unit and bed label are required.");
        }

        return new Bed { FacilityId = string.IsNullOrWhiteSpace(facilityId) ? FacilityDirectory.DefaultFacilityId : facilityId.Trim(), Unit = unit.Trim(), Label = label.Trim(), Status = BedStatus.Available };
    }

    public Result Assign(Guid stayId)
    {
        return Status switch
        {
            BedStatus.Occupied => Error.Conflict("bed.occupied", $"{Display} is occupied."),
            BedStatus.OutOfService => Error.Conflict("bed.out_of_service", $"{Display} is out of service: {OutOfServiceReason}"),
            _ => Occupy(stayId),
        };
    }

    public void Vacate()
    {
        Status = BedStatus.Available;
        OccupiedByStayId = null;
    }

    public Result TakeOutOfService(string reason)
    {
        if (Status == BedStatus.Occupied)
        {
            return Error.Conflict("bed.occupied", "Move the resident before taking the bed out of service.");
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("bed.reason_required", "A reason is required.");
        }

        Status = BedStatus.OutOfService;
        OutOfServiceReason = reason.Trim();
        return Result.Success();
    }

    public Result ReturnToService()
    {
        if (Status != BedStatus.OutOfService)
        {
            return Error.Conflict("bed.in_service", "The bed is already in service.");
        }

        Status = BedStatus.Available;
        OutOfServiceReason = null;
        return Result.Success();
    }

    private Result Occupy(Guid stayId)
    {
        Status = BedStatus.Occupied;
        OccupiedByStayId = stayId;
        return Result.Success();
    }
}

namespace CareConnector.Modules.Census.Domain;

internal enum ReconciliationStatus
{
    /// <summary>Both systems have the resident in the facility.</summary>
    Matched,

    /// <summary>CareConnector has an open stay the census system of record does not show.</summary>
    OnlyInCareConnector,

    /// <summary>The system of record shows a resident CareConnector has not admitted.</summary>
    OnlyInSource,
}

internal sealed record LocalResident(Guid StayId, Guid ClientId, string DisplayName, string LegalFirstName, string LegalLastName, DateOnly DateOfBirth, string Bed, string? ExternalResidentId);

internal sealed record SourceResident(string ResidentId, string? ResidentNumber, string DisplayName, string? FirstName, string? LastName, DateOnly? DateOfBirth, string? Unit);

internal sealed record ReconciliationRow(
    ReconciliationStatus Status, LocalResident? Local, SourceResident? Source, string MatchedBy);

/// <summary>
/// Compares CareConnector's open stays with the census system of record. Matching is deterministic and conservative:
/// a linked resident id first, otherwise exact legal last name + first name + date of birth. Anything less is
/// reported as unmatched for a person to resolve; the reconciliation never links or changes records on its own.
/// </summary>
internal static class CensusReconciliation
{
    public static IReadOnlyList<ReconciliationRow> Reconcile(IReadOnlyCollection<LocalResident> local, IReadOnlyCollection<SourceResident> source)
    {
        ArgumentNullException.ThrowIfNull(local);
        ArgumentNullException.ThrowIfNull(source);

        var rows = new List<ReconciliationRow>();
        var unmatchedSource = source.ToList();

        foreach (var l in local)
        {
            var byId = l.ExternalResidentId is null ? null : unmatchedSource.FirstOrDefault(s => s.ResidentId == l.ExternalResidentId || s.ResidentNumber == l.ExternalResidentId);
            var byIdentity = byId ?? unmatchedSource.FirstOrDefault(s =>
                s.DateOfBirth == l.DateOfBirth && Same(s.LastName, l.LegalLastName) && Same(s.FirstName, l.LegalFirstName));

            if (byIdentity is null)
            {
                rows.Add(new ReconciliationRow(ReconciliationStatus.OnlyInCareConnector, l, null, ""));
                continue;
            }

            unmatchedSource.Remove(byIdentity);
            rows.Add(new ReconciliationRow(ReconciliationStatus.Matched, l, byIdentity, byId is not null ? "Resident id" : "Name and date of birth"));
        }

        rows.AddRange(unmatchedSource.Select(s => new ReconciliationRow(ReconciliationStatus.OnlyInSource, null, s, "")));
        return rows;
    }

    private static bool Same(string? a, string? b) =>
        a is not null && b is not null && string.Equals(a.Trim(), b.Trim(), StringComparison.OrdinalIgnoreCase);
}

using CareConnector.Modules.Census.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.Census.Domain;

/// <summary>A resident's residential episode: which bed, whether they are in the building, and any holds.</summary>
internal sealed class Stay : AggregateRoot
{
    /// <summary>Longest pass the program allows before it must be a discharge.</summary>
    public static readonly TimeSpan MaximumPass = TimeSpan.FromHours(72);

    private Stay()
    {
    }

    public Guid ClientId { get; private set; }

    public Guid BedId { get; private set; }

    /// <summary>Facility of the current bed (platform facility id).</summary>
    public string FacilityId { get; private set; } = FacilityDirectory.DefaultFacilityId;

    public string BedDisplay { get; private set; } = "";

    public string Unit { get; private set; } = "";

    public StayStatus Status { get; private set; }

    public DateTimeOffset AdmittedAt { get; private set; }

    public string AdmittedBy { get; private set; } = "";

    /// <summary>Resident identifier in the census system of record (via the Alamo platform), when linked.</summary>
    public string? ExternalResidentId { get; private set; }

    public PassKind? PassKind { get; private set; }

    public string? PassDestination { get; private set; }

    public DateTimeOffset? PassStartedAt { get; private set; }

    public DateTimeOffset? PassDueBackAt { get; private set; }

    public DateTimeOffset? AwolReportedAt { get; private set; }

    public DateTimeOffset? AwolLastSeenAt { get; private set; }

    public string? AwolLastSeenLocation { get; private set; }

    public string? AwolNotifications { get; private set; }

    public DateTimeOffset? DischargedAt { get; private set; }

    public DischargeType? DischargeType { get; private set; }

    public string? DischargeNote { get; private set; }

    public List<Hold> Holds { get; private set; } = [];

    public List<Movement> Movements { get; private set; } = [];

    public bool IsOpen => Status != StayStatus.Discharged;

    /// <summary>When the resident's presence last changed (admitted, left, returned).</summary>
    public DateTimeOffset StatusSince => Movements
        .Where(m => m.Kind is MovementKind.Admitted or MovementKind.PassStarted or MovementKind.PassReturned or MovementKind.AwolReported or MovementKind.AwolReturned)
        .Select(m => m.At)
        .DefaultIfEmpty(AdmittedAt)
        .Max();

    /// <summary>
    /// Where the resident was at a past moment, read from the movement history. A tap made on a tablet with no
    /// connection is judged by where the resident was when it was tapped, not where they are when it arrives.
    /// Null before the admission.
    /// </summary>
    public PresenceStatus? PresenceAt(DateTimeOffset at) => Movements
        .Where(m => m.At <= at && m.Kind is MovementKind.Admitted or MovementKind.PassStarted or MovementKind.PassReturned or MovementKind.AwolReported or MovementKind.AwolReturned)
        .Where(m => m.At <= at)
        .OrderBy(m => m.At)
        .Select(m => (PresenceStatus?)(m.Kind switch
        {
            MovementKind.PassStarted => PresenceStatus.OnPass,
            MovementKind.AwolReported => PresenceStatus.Awol,
            _ => PresenceStatus.InHouse,
        }))
        .LastOrDefault();

    public bool HasRestrictiveHold(DateTimeOffset now) => Holds.Any(h => h.RestrictsLeave && h.IsActive(now));

    public bool IsPassOverdue(DateTimeOffset now) => Status == StayStatus.OnPass && now > PassDueBackAt;

    public static Result<Stay> Admit(Guid clientId, Bed bed, string? externalResidentId, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(bed);
        ArgumentNullException.ThrowIfNull(user);

        var stay = new Stay
        {
            ClientId = clientId,
            BedId = bed.Id,
            FacilityId = bed.FacilityId,
            BedDisplay = bed.Display,
            Unit = bed.Unit,
            Status = StayStatus.InHouse,
            AdmittedAt = now,
            AdmittedBy = user.UserId,
            ExternalResidentId = string.IsNullOrWhiteSpace(externalResidentId) ? null : externalResidentId.Trim(),
        };

        var assigned = bed.Assign(stay.Id);
        if (!assigned.IsSuccess)
        {
            return assigned.Error!;
        }

        stay.Log(MovementKind.Admitted, $"Admitted to {bed.Display}", user, now);
        stay.Raise(new ResidentAdmitted(stay.Id, clientId, bed.Unit, bed.Label, now));
        return stay;
    }

    public Result MoveTo(Bed current, Bed target, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(current);
        ArgumentNullException.ThrowIfNull(target);

        if (!IsOpen)
        {
            return Error.Conflict("stay.discharged", "The resident is discharged.");
        }

        if (target.Id == BedId)
        {
            return Error.Conflict("stay.same_bed", "The resident is already in that bed.");
        }

        var assigned = target.Assign(Id);
        if (!assigned.IsSuccess)
        {
            return assigned;
        }

        current.Vacate();
        var from = BedDisplay;
        BedId = target.Id;
        FacilityId = target.FacilityId;
        BedDisplay = target.Display;
        Unit = target.Unit;
        Log(MovementKind.BedChanged, $"{from} → {target.Display}", user, now);
        Raise(new ResidentMovedBed(Id, ClientId, from, target.Display, now));
        return Result.Success();
    }

    public Result StartPass(PassKind kind, string destination, DateTimeOffset dueBackAt, ICurrentUser user, DateTimeOffset now, string? tapKey = null)
    {
        if (Status != StayStatus.InHouse)
        {
            return Error.Conflict("pass.not_in_house", "Passes start only for residents who are in the building.");
        }

        if (HasRestrictiveHold(now))
        {
            return new Error("pass.hold_active", "An active hold restricts leave. Release it before starting a pass.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(destination))
        {
            return new Error("pass.destination_required", "Record where the resident is going.");
        }

        if (dueBackAt <= now || dueBackAt - now > MaximumPass)
        {
            return new Error("pass.invalid_return", $"The expected return must be in the future and within {MaximumPass.TotalHours:0} hours.");
        }

        Status = StayStatus.OnPass;
        PassKind = kind;
        PassDestination = destination.Trim();
        PassStartedAt = now;
        PassDueBackAt = dueBackAt;
        Log(MovementKind.PassStarted, $"{kind} pass to {PassDestination}, due back {dueBackAt:u}", user, now, tapKey);
        Raise(new PassStarted(Id, ClientId, kind.ToString(), dueBackAt, now));
        return Result.Success();
    }

    public Result ReturnFromPass(ICurrentUser user, DateTimeOffset now, string? tapKey = null)
    {
        if (Status != StayStatus.OnPass)
        {
            return Error.Conflict("pass.not_on_pass", "The resident is not on a pass.");
        }

        var late = now > PassDueBackAt;
        var detail = late ? $"Returned {(int)(now - PassDueBackAt!.Value).TotalMinutes} min late" : "Returned on time";
        ClearPass();
        Status = StayStatus.InHouse;
        Log(MovementKind.PassReturned, detail, user, now, tapKey);
        Raise(new PassReturned(Id, ClientId, late, now));
        return Result.Success();
    }

    public Result ReportAwol(DateTimeOffset lastSeenAt, string lastSeenLocation, string notifications, ICurrentUser user, DateTimeOffset now, string? tapKey = null)
    {
        if (Status is not (StayStatus.InHouse or StayStatus.OnPass))
        {
            return Error.Conflict("awol.invalid_state", $"Cannot report AWOL for a resident who is {Status}.");
        }

        if (lastSeenAt > now)
        {
            return new Error("awol.invalid_last_seen", "Last seen time cannot be in the future.");
        }

        if (string.IsNullOrWhiteSpace(lastSeenLocation) || string.IsNullOrWhiteSpace(notifications))
        {
            return new Error("awol.details_required", "Record where the resident was last seen and who has been notified.");
        }

        ClearPass();
        Status = StayStatus.Awol;
        AwolReportedAt = now;
        AwolLastSeenAt = lastSeenAt;
        AwolLastSeenLocation = lastSeenLocation.Trim();
        AwolNotifications = notifications.Trim();
        var onHold = HasRestrictiveHold(now);
        Log(MovementKind.AwolReported, $"Last seen {lastSeenAt:u} at {AwolLastSeenLocation}{(onHold ? " while on a restrictive hold" : "")}", user, now, tapKey);
        Raise(new ResidentAwol(Id, ClientId, onHold, lastSeenAt, now));
        return Result.Success();
    }

    public Result ReturnFromAwol(string note, ICurrentUser user, DateTimeOffset now, string? tapKey = null)
    {
        if (Status != StayStatus.Awol)
        {
            return Error.Conflict("awol.not_awol", "The resident is not AWOL.");
        }

        if (string.IsNullOrWhiteSpace(note))
        {
            return new Error("awol.return_note_required", "Record the resident's condition on return.");
        }

        Status = StayStatus.InHouse;
        Log(MovementKind.AwolReturned, note.Trim(), user, now, tapKey);
        Raise(new ResidentReturnedFromAwol(Id, ClientId, now));
        return Result.Success();
    }

    public Result<Hold> PlaceHold(HoldType type, string reason, bool restrictsLeave, DateTimeOffset? expiresAt, ICurrentUser user, DateTimeOffset now)
    {
        if (ActorRules.RequireHuman(user, "Placing a hold") is { } humanError)
        {
            return humanError;
        }

        if (!IsOpen)
        {
            return Error.Conflict("stay.discharged", "The resident is discharged.");
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("hold.reason_required", "Record the reason and authority for the hold.");
        }

        if (expiresAt <= now)
        {
            return new Error("hold.invalid_expiry", "A hold cannot expire in the past.");
        }

        var hold = new Hold
        {
            Id = Guid.CreateVersion7(),
            Type = type,
            Reason = reason.Trim(),
            RestrictsLeave = restrictsLeave,
            PlacedAt = now,
            PlacedBy = user.DisplayName,
            ExpiresAt = expiresAt,
        };
        Holds = [.. Holds, hold];
        Log(MovementKind.HoldPlaced, $"{type} hold{(restrictsLeave ? " (restricts leave)" : "")}", user, now);
        Raise(new HoldPlaced(Id, ClientId, hold.Id, type.ToString(), restrictsLeave, now));
        return hold;
    }

    public Result ReleaseHold(Guid holdId, string note, ICurrentUser user, DateTimeOffset now)
    {
        var hold = Holds.FirstOrDefault(h => h.Id == holdId);
        if (hold is null)
        {
            return Error.NotFound("hold.not_found", "Hold not found.");
        }

        if (hold.ReleasedAt is not null)
        {
            return Error.Conflict("hold.released", "The hold is already released.");
        }

        if (string.IsNullOrWhiteSpace(note))
        {
            return new Error("hold.release_note_required", "Record why the hold is released.");
        }

        var released = new Hold
        {
            Id = hold.Id,
            Type = hold.Type,
            Reason = hold.Reason,
            RestrictsLeave = hold.RestrictsLeave,
            PlacedAt = hold.PlacedAt,
            PlacedBy = hold.PlacedBy,
            ExpiresAt = hold.ExpiresAt,
            ReleasedAt = now,
            ReleasedBy = user.DisplayName,
            ReleaseNote = note.Trim(),
        };
        Holds = [.. Holds.Select(h => h.Id == holdId ? released : h)];
        Log(MovementKind.HoldReleased, $"{hold.Type} hold released", user, now);
        Raise(new HoldReleased(Id, ClientId, holdId, now));
        return Result.Success();
    }

    public Result Discharge(DischargeType type, string note, Bed bed, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(bed);

        if (ActorRules.RequireHuman(user, "Discharging a resident") is { } humanError)
        {
            return humanError;
        }

        if (!IsOpen)
        {
            return Error.Conflict("stay.discharged", "The resident is already discharged.");
        }

        if (Status == StayStatus.Awol && type != Domain.DischargeType.Awol)
        {
            return Error.Conflict("discharge.awol", "A resident who is AWOL can only be discharged as AWOL, or returned first.");
        }

        if (type == Domain.DischargeType.Awol && Status != StayStatus.Awol)
        {
            return Error.Conflict("discharge.not_awol", "An AWOL discharge requires the resident to be reported AWOL first.");
        }

        if (HasRestrictiveHold(now) && type is not (Domain.DischargeType.TransferHigherLevelOfCare or Domain.DischargeType.Awol))
        {
            return new Error("discharge.hold_active", "An active hold restricts leave. Release it, or discharge as a transfer to a higher level of care.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(note))
        {
            return new Error("discharge.note_required", "A discharge note is required.");
        }

        ClearPass();
        Status = StayStatus.Discharged;
        DischargedAt = now;
        DischargeType = type;
        DischargeNote = note.Trim();
        bed.Vacate();
        Log(MovementKind.Discharged, $"{type}: {DischargeNote}", user, now);
        Raise(new ResidentDischarged(Id, ClientId, type.ToString(), now));
        return Result.Success();
    }

    public PresenceStatus? Presence => Status switch
    {
        StayStatus.InHouse => PresenceStatus.InHouse,
        StayStatus.OnPass => PresenceStatus.OnPass,
        StayStatus.Awol => PresenceStatus.Awol,
        _ => null,
    };

    private void ClearPass()
    {
        PassKind = null;
        PassDestination = null;
        PassStartedAt = null;
        PassDueBackAt = null;
    }

    /// <summary>True when a movement was already recorded for this tap: the tablet is sending it again.</summary>
    public bool HasTap(string tapKey) => Movements.Any(m => m.Key == tapKey);

    private void Log(MovementKind kind, string detail, ICurrentUser user, DateTimeOffset now, string? tapKey = null) =>
        Movements = [.. Movements, new Movement { At = now, Kind = kind, Detail = detail, By = user.DisplayName, Key = tapKey }];
}

namespace CareConnector.Modules.Census.Domain;

internal enum StayStatus
{
    InHouse,
    OnPass,
    Awol,
    Discharged,
}

internal enum PassKind
{
    Therapeutic,
    MedicalAppointment,
    Court,
    Family,
    Employment,

    /// <summary>Signed out for a personal errand or walk; the everyday case in an unlocked facility.</summary>
    Personal,
}

/// <summary>Holds are recorded as facts; the legal authority (e.g. a state involuntary hold statute) is in the reason.</summary>
internal enum HoldType
{
    InvoluntaryHold,
    CourtOrder,
    Conservatorship,
    ClinicalRestriction,
    Administrative,
}

internal enum DischargeType
{
    Planned,
    AgainstMedicalAdvice,
    Awol,
    TransferHigherLevelOfCare,
    Administrative,
}

internal enum MovementKind
{
    Admitted,
    BedChanged,
    PassStarted,
    PassReturned,
    AwolReported,
    AwolReturned,
    HoldPlaced,
    HoldReleased,
    Discharged,
}

internal sealed class Hold
{
    public required Guid Id { get; init; }

    public required HoldType Type { get; init; }

    public required string Reason { get; init; }

    public required bool RestrictsLeave { get; init; }

    public required DateTimeOffset PlacedAt { get; init; }

    public required string PlacedBy { get; init; }

    public DateTimeOffset? ExpiresAt { get; init; }

    public DateTimeOffset? ReleasedAt { get; init; }

    public string? ReleasedBy { get; init; }

    public string? ReleaseNote { get; init; }

    public bool IsActive(DateTimeOffset now) => ReleasedAt is null && (ExpiresAt is null || ExpiresAt > now);
}

/// <summary>One line of the stay's movement history; the audit log records who changed the row, this records what happened.</summary>
internal sealed class Movement
{
    public required DateTimeOffset At { get; init; }

    public required MovementKind Kind { get; init; }

    public required string Detail { get; init; }

    public required string By { get; init; }

    /// <summary>The tablet's id for the tap that caused this, when it came from one, so a resend is recognised.</summary>
    public string? Key { get; init; }
}

using CareConnector.Modules.Clients.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.Clients.Domain;

internal enum ClientStatus
{
    Active,
    Discharged,
}

internal sealed class Client : AggregateRoot
{
    private Client()
    {
    }

    /// <summary>Sequential number assigned by the database; shown to staff as the record number.</summary>
    public long Number { get; private set; }

    public string RecordNumber => $"CC-{Number:D6}";

    public string LegalFirstName { get; private set; } = "";

    public string LegalLastName { get; private set; } = "";

    public string? PreferredName { get; private set; }

    public string? Pronouns { get; private set; }

    public DateOnly DateOfBirth { get; private set; }

    public ClientStatus Status { get; private set; }

    public DateTimeOffset AdmittedAt { get; private set; }

    public DateTimeOffset? DischargedAt { get; private set; }

    public string? DischargeReason { get; private set; }

    /// <summary>Name staff use when addressing the client: preferred name first, as a matter of care.</summary>
    public string DisplayName => $"{PreferredName ?? LegalFirstName} {LegalLastName}";

    public static Result<Client> Admit(
        string legalFirstName, string legalLastName, string? preferredName, string? pronouns, DateOnly dateOfBirth, DateTimeOffset now)
    {
        if (string.IsNullOrWhiteSpace(legalFirstName) || string.IsNullOrWhiteSpace(legalLastName))
        {
            return new Error("client.name_required", "Legal first and last name are required.");
        }

        if (dateOfBirth > DateOnly.FromDateTime(now.UtcDateTime) || dateOfBirth.Year < 1900)
        {
            return new Error("client.invalid_date_of_birth", "Date of birth must be a real date in the past.");
        }

        var client = new Client
        {
            LegalFirstName = legalFirstName.Trim(),
            LegalLastName = legalLastName.Trim(),
            PreferredName = Normalize(preferredName),
            Pronouns = Normalize(pronouns),
            DateOfBirth = dateOfBirth,
            Status = ClientStatus.Active,
            AdmittedAt = now,
        };
        client.Raise(new ClientAdmitted(client.Id, now));
        return client;
    }

    public void UpdateIdentity(string? preferredName, string? pronouns)
    {
        PreferredName = Normalize(preferredName);
        Pronouns = Normalize(pronouns);
    }

    public Result Discharge(string reason, DateTimeOffset now)
    {
        if (Status == ClientStatus.Discharged)
        {
            return Error.Conflict("client.already_discharged", "Client is already discharged.");
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("client.discharge_reason_required", "A discharge reason is required.");
        }

        Status = ClientStatus.Discharged;
        DischargedAt = now;
        DischargeReason = reason.Trim();
        Raise(new ClientDischarged(Id, DischargeReason, now));
        return Result.Success();
    }

    public Result Readmit(DateTimeOffset now)
    {
        if (Status == ClientStatus.Active)
        {
            return Error.Conflict("client.already_active", "Client is already active.");
        }

        Status = ClientStatus.Active;
        AdmittedAt = now;
        DischargedAt = null;
        DischargeReason = null;
        Raise(new ClientAdmitted(Id, now));
        return Result.Success();
    }

    private static string? Normalize(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}

