namespace CareConnector.Modules.Consent.Domain;

internal enum AccessKind
{
    /// <summary>A resident's screen was shown to this person. Reported by the screen itself, so it holds with no connection.</summary>
    Viewed,

    /// <summary>The server answered this person's read of one resident's record.</summary>
    Fetched,

    /// <summary>The tablet read the record ahead to keep a copy; nobody had opened it yet.</summary>
    HeldOnTablet,

    /// <summary>The person saw a list that included residents' records (a roster, a round).</summary>
    Listed,

    /// <summary>The gate refused records to this person.</summary>
    Denied,
}

/// <summary>
/// One line of the record of who looked at whose record. It is itself a record: lines are only ever added, never
/// changed or removed. It names the resident and the screen, never what the record said.
/// </summary>
internal sealed class AccessEntry
{
    private AccessEntry()
    {
    }

    public Guid Id { get; private set; } = Guid.CreateVersion7();

    public string UserId { get; private set; } = "";

    public string UserName { get; private set; } = "";

    /// <summary>Null for a list of several residents.</summary>
    public Guid? ClientId { get; private set; }

    public AccessKind Kind { get; private set; }

    /// <summary>The screen or the question: "Services", "/api/clients/{clientId}/services". Never content.</summary>
    public string What { get; private set; } = "";

    public DateTimeOffset At { get; private set; }

    /// <summary>How many records (or, for a list, residents) this line stands for.</summary>
    public int Count { get; private set; }

    /// <summary>Seen under emergency access.</summary>
    public bool Emergency { get; private set; }

    public Guid? TabletId { get; private set; }

    /// <summary>The tablet's own key for a view it reported, so one sent twice is logged once.</summary>
    public Guid? ClientKey { get; private set; }

    public static AccessEntry Note(ICurrentUser user, Guid? clientId, AccessKind kind, string what, int count, DateTimeOffset at, bool emergency, Guid? tabletId, Guid? clientKey = null)
    {
        ArgumentNullException.ThrowIfNull(user);
        ArgumentNullException.ThrowIfNull(what);
        return new AccessEntry
        {
            UserId = user.UserId,
            UserName = user.DisplayName,
            ClientId = clientId,
            Kind = kind,
            What = what.Length > 160 ? what[..160] : what,
            Count = Math.Max(1, count),
            At = at,
            Emergency = emergency,
            TabletId = tabletId,
            ClientKey = clientKey,
        };
    }
}

/// <summary>
/// A person who does not normally have access to a resident's record takes it, for a stated reason and a limited
/// time, because someone's safety needs it now. It is never refused at the moment it is asked for: it is recorded,
/// shown to them as recorded, and reviewed by a supervisor afterwards. It opens what clinical staff see; it never
/// opens counseling notes.
/// </summary>
internal sealed class EmergencyAccess : AggregateRoot
{
    /// <summary>Long enough to deal with what is happening; short enough that it has to be asked for again tomorrow.</summary>
    public static readonly TimeSpan Lasts = TimeSpan.FromMinutes(60);

    public const int ShortestReason = 10;

    private EmergencyAccess()
    {
    }

    public Guid ClientId { get; private set; }

    public string UserId { get; private set; } = "";

    public string UserName { get; private set; } = "";

    public string Reason { get; private set; } = "";

    public DateTimeOffset StartedAt { get; private set; }

    public DateTimeOffset EndsAt { get; private set; }

    public string? ReviewedBy { get; private set; }

    public string? ReviewedByName { get; private set; }

    public DateTimeOffset? ReviewedAt { get; private set; }

    public string? ReviewNote { get; private set; }

    public bool IsReviewed => ReviewedAt is not null;

    public bool IsActiveAt(DateTimeOffset now) => now >= StartedAt && now < EndsAt;

    public static Result<EmergencyAccess> Take(Guid clientId, string? reason, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Emergency access") is { } humanError)
        {
            return humanError;
        }

        if (string.IsNullOrWhiteSpace(reason) || reason.Trim().Length < ShortestReason)
        {
            return new Error("emergency.reason_required", "Say why you need this resident's record now. It is recorded and reviewed.");
        }

        return new EmergencyAccess
        {
            ClientId = clientId,
            UserId = user.UserId,
            UserName = user.DisplayName,
            Reason = reason.Trim(),
            StartedAt = now,
            EndsAt = now + Lasts,
        };
    }

    /// <summary>A supervisor has looked at it. They cannot review their own.</summary>
    public Result Review(string? note, ICurrentUser reviewer, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(reviewer);
        if (!reviewer.IsInRole(Roles.Supervisor) && !reviewer.IsInRole(Roles.Administrator))
        {
            return new Error("emergency.review_forbidden", "A supervisor reviews emergency access.", ErrorKind.Forbidden);
        }

        if (reviewer.UserId == UserId)
        {
            return new Error("emergency.review_own", "Someone else has to review your own emergency access.", ErrorKind.Forbidden);
        }

        if (IsReviewed)
        {
            return Error.Conflict("emergency.already_reviewed", "This has already been reviewed.");
        }

        if (string.IsNullOrWhiteSpace(note))
        {
            return new Error("emergency.note_required", "Say what you found: whether the access was warranted.");
        }

        ReviewedBy = reviewer.UserId;
        ReviewedByName = reviewer.DisplayName;
        ReviewedAt = now;
        ReviewNote = note.Trim();
        return Result.Success();
    }
}

using CareConnector.Modules.Consent.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.Consent.Domain;

/// <summary>The written consent as signed, captured field by field so every §2.31(a) element is verifiable.</summary>
internal sealed record ConsentForm(
    ConsentScope Scope,
    string DisclosingProgram,
    string InformationDescription,
    string RecipientDesignation,
    string Purpose,
    ExpirationKind ExpirationKind,
    DateOnly? ExpiresOn,
    string SignedByName,
    SignerRole SignerRole,
    DateOnly SignedOn,
    bool IncludesRevocationStatement,
    bool IncludesRedisclosureStatement,
    bool IncludesRefusalConsequencesStatement);

/// <summary>
/// A 42 CFR Part 2 written consent. Never edited or deleted after recording; a changed consent is a revocation
/// plus a new consent. Revocation does not undo disclosures already made in reliance on it.
/// </summary>
internal sealed class Consent : AggregateRoot
{
    private Consent()
    {
    }

    public Guid ClientId { get; private set; }

    public ConsentScope Scope { get; private set; }

    public string DisclosingProgram { get; private set; } = "";

    public string InformationDescription { get; private set; } = "";

    public string RecipientDesignation { get; private set; } = "";

    public string Purpose { get; private set; } = "";

    public ExpirationKind ExpirationKind { get; private set; }

    public DateOnly? ExpiresOn { get; private set; }

    public string SignedByName { get; private set; } = "";

    public SignerRole SignerRole { get; private set; }

    public DateOnly SignedOn { get; private set; }

    public string RecordedBy { get; private set; } = "";

    public DateTimeOffset RecordedAt { get; private set; }

    public ConsentStatus Status { get; private set; }

    public DateOnly? RevokedOn { get; private set; }

    public string? RevocationNote { get; private set; }

    public static Result<Consent> Record(Guid clientId, ConsentForm form, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(form);
        ArgumentNullException.ThrowIfNull(user);

        if (ActorRules.RequireHuman(user, "Recording a consent") is { } humanError)
        {
            return humanError;
        }

        if (Validate(form, DateOnly.FromDateTime(now.UtcDateTime)) is { } error)
        {
            return error;
        }

        var consent = new Consent
        {
            ClientId = clientId,
            Scope = form.Scope,
            DisclosingProgram = form.DisclosingProgram.Trim(),
            InformationDescription = form.InformationDescription.Trim(),
            RecipientDesignation = form.RecipientDesignation.Trim(),
            Purpose = form.Purpose.Trim(),
            ExpirationKind = form.ExpirationKind,
            ExpiresOn = form.ExpirationKind == ExpirationKind.OnDate ? form.ExpiresOn : null,
            SignedByName = form.SignedByName.Trim(),
            SignerRole = form.SignerRole,
            SignedOn = form.SignedOn,
            RecordedBy = user.UserId,
            RecordedAt = now,
            Status = ConsentStatus.Active,
        };
        consent.Raise(new ConsentRecorded(consent.Id, clientId, form.Scope.ToString(), now));
        return consent;
    }

    /// <summary>Whether the consent can authorize a use or disclosure on <paramref name="today"/>.</summary>
    public bool IsEffective(DateOnly today, bool clientInTreatment) =>
        Status == ConsentStatus.Active && ExpirationKind switch
        {
            ExpirationKind.OnDate => today <= ExpiresOn,
            ExpirationKind.EndOfTreatment => clientInTreatment,
            _ => true,
        };

    /// <summary>
    /// Records a revocation. Since the 2024 rule, revocation must be in writing (§2.31(a)(6)); staff attest that the
    /// written revocation was received and when.
    /// </summary>
    public Result Revoke(DateOnly receivedOn, bool receivedInWriting, string? note, DateTimeOffset now)
    {
        if (Status == ConsentStatus.Revoked)
        {
            return Error.Conflict("consent.already_revoked", "This consent is already revoked.");
        }

        if (!receivedInWriting)
        {
            return new Error("consent.revocation_not_written", "Part 2 consent revocations must be received in writing.");
        }

        if (receivedOn < SignedOn || receivedOn > DateOnly.FromDateTime(now.UtcDateTime))
        {
            return new Error("consent.invalid_revocation_date", "The revocation date must be between the signing date and today.");
        }

        Status = ConsentStatus.Revoked;
        RevokedOn = receivedOn;
        RevocationNote = string.IsNullOrWhiteSpace(note) ? null : note.Trim();
        Raise(new ConsentRevoked(Id, ClientId, Scope.ToString(), now));
        return Result.Success();
    }

    private static Error? Validate(ConsentForm f, DateOnly today)
    {
        string[] required = [f.DisclosingProgram, f.InformationDescription, f.RecipientDesignation, f.Purpose, f.SignedByName];
        if (required.Any(string.IsNullOrWhiteSpace))
        {
            return new Error(
                "consent.missing_element",
                "A Part 2 consent needs the disclosing program, a description of the information, the recipients, the purpose and the signer's name.");
        }

        if (f.SignedOn > today)
        {
            return new Error("consent.future_signature", "The signing date cannot be in the future.");
        }

        if (!f.IncludesRevocationStatement)
        {
            return new Error("consent.missing_revocation_statement", "The consent must state the patient's right to revoke in writing and how to do so.");
        }

        if (f.Scope == ConsentScope.TreatmentPaymentOperations && !(f.IncludesRedisclosureStatement && f.IncludesRefusalConsequencesStatement))
        {
            return new Error(
                "consent.missing_tpo_statements",
                "A TPO consent must state that records may be redisclosed under HIPAA and the consequences of refusing to sign.");
        }

        return f.ExpirationKind switch
        {
            ExpirationKind.OnDate when f.ExpiresOn is null => new Error("consent.expiration_required", "Enter the expiration date."),
            ExpirationKind.OnDate when f.ExpiresOn < f.SignedOn => new Error("consent.invalid_expiration", "The consent cannot expire before it was signed."),
            ExpirationKind.None or ExpirationKind.EndOfTreatment when f.Scope != ConsentScope.TreatmentPaymentOperations =>
                new Error("consent.expiration_not_allowed", "Only a TPO consent may expire at the end of treatment or have no expiration; set a date."),
            _ => null,
        };
    }
}

namespace CareConnector.Modules.Consent.Domain;

/// <summary>
/// What a consent authorizes. Kinds that §2.31 forbids combining with other purposes are separate scopes,
/// so one consent can never cover them together with anything else.
/// Use in civil, criminal, administrative or legislative proceedings is deliberately not a scope: it needs a
/// standalone consent plus a court order (§2.31(d), §§2.64–2.67) and is handled outside this system.
/// </summary>
internal enum ConsentScope
{
    /// <summary>Single consent for all future treatment, payment and health care operations uses and disclosures (§2.33(b)).</summary>
    TreatmentPaymentOperations,

    /// <summary>Use or disclosure of SUD counseling notes. Must stand alone (§2.31(b)).</summary>
    CounselingNotes,

    /// <summary>Disclosure to a named recipient for a stated purpose (e.g. a probation officer, an employer, family).</summary>
    SpecificDisclosure,
}

internal enum ExpirationKind
{
    /// <summary>Expires at the end of the day on <c>ExpiresOn</c>.</summary>
    OnDate,

    /// <summary>Expires when the resident is discharged. The regulation's "end of the treatment" (TPO only).</summary>
    EndOfTreatment,

    /// <summary>No expiration. Permitted for TPO consents only.</summary>
    None,
}

internal enum SignerRole
{
    Patient,
    Guardian,
    AuthorizedRepresentative,
}

internal enum ConsentStatus
{
    Active,
    Revoked,
}

internal enum DisclosurePurpose
{
    Treatment,
    Payment,
    HealthCareOperations,
    Other,
}

internal enum DisclosureBasis
{
    /// <summary>Written patient consent (§2.31–2.33).</summary>
    Consent,

    /// <summary>Bona fide medical emergency; no consent required but must be documented (§2.51).</summary>
    MedicalEmergency,
}

using CareConnector.Modules.Consent.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.Consent.Domain;

/// <summary>
/// One disclosure of a resident's records outside the program: the source for the accounting of disclosures
/// (§2.25) and the record of which notice accompanied it (§2.32). Immutable once recorded.
/// </summary>
internal sealed class Disclosure : AggregateRoot
{
    private Disclosure()
    {
    }

    public Guid ClientId { get; private set; }

    public DisclosureBasis Basis { get; private set; }

    public Guid? ConsentId { get; private set; }

    public string Recipient { get; private set; } = "";

    public DisclosurePurpose Purpose { get; private set; }

    public string PurposeDetail { get; private set; } = "";

    public string RecordsDescription { get; private set; } = "";

    public List<SensitivityLabel> Labels { get; private set; } = [];

    /// <summary>For medical emergencies (§2.51(c)): the nature of the emergency.</summary>
    public string? EmergencyDescription { get; private set; }

    public string DisclosedBy { get; private set; } = "";

    public string DisclosedByName { get; private set; } = "";

    public DateTimeOffset DisclosedAt { get; private set; }

    /// <summary>The §2.32 statement and consent-scope explanation that went with the records, as sent.</summary>
    public string AccompanyingNotice { get; private set; } = "";

    public static Result<Disclosure> Record(
        Guid clientId,
        DisclosureBasis basis,
        Consent? consent,
        string recipient,
        DisclosurePurpose purpose,
        string purposeDetail,
        string recordsDescription,
        IReadOnlyCollection<SensitivityLabel> labels,
        string? emergencyDescription,
        bool clientInTreatment,
        ICurrentUser user,
        DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        ArgumentNullException.ThrowIfNull(labels);

        if (ActorRules.RequireHuman(user, "Disclosing records") is { } humanError)
        {
            return humanError;
        }

        if (string.IsNullOrWhiteSpace(recipient) || string.IsNullOrWhiteSpace(recordsDescription) || string.IsNullOrWhiteSpace(purposeDetail))
        {
            return new Error("disclosure.missing_details", "Record the recipient, the purpose and what was disclosed.");
        }

        if (basis == DisclosureBasis.MedicalEmergency && string.IsNullOrWhiteSpace(emergencyDescription))
        {
            return new Error("disclosure.emergency_details", "Describe the nature of the medical emergency.");
        }

        if (consent is not null && consent.ClientId != clientId)
        {
            return new Error("disclosure.consent_mismatch", "The consent belongs to a different resident.", ErrorKind.Forbidden);
        }

        var authorized = DisclosurePolicy.Authorize(labels, basis, purpose, basis == DisclosureBasis.Consent ? consent : null, DateOnly.FromDateTime(now.UtcDateTime), clientInTreatment);
        if (!authorized.IsSuccess)
        {
            return authorized.Error!;
        }

        var part2 = labels.Any(l => l != SensitivityLabel.General);
        var notice = !part2
            ? ""
            : basis == DisclosureBasis.Consent
                ? $"{RedisclosureNotice.Full}\n\n{RedisclosureNotice.ExplainScope(consent!)}"
                : RedisclosureNotice.Full;

        var disclosure = new Disclosure
        {
            ClientId = clientId,
            Basis = basis,
            ConsentId = basis == DisclosureBasis.Consent ? consent?.Id : null,
            Recipient = recipient.Trim(),
            Purpose = purpose,
            PurposeDetail = purposeDetail.Trim(),
            RecordsDescription = recordsDescription.Trim(),
            Labels = [.. labels.Distinct()],
            EmergencyDescription = emergencyDescription?.Trim(),
            DisclosedBy = user.UserId,
            DisclosedByName = user.DisplayName,
            DisclosedAt = now,
            AccompanyingNotice = notice,
        };
        disclosure.Raise(new RecordsDisclosed(disclosure.Id, clientId, basis.ToString(), disclosure.Recipient, now));
        return disclosure;
    }
}

using CareConnector.Modules.Consent.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.Consent.Domain;

/// <summary>
/// Decides whether a disclosure of records outside the program is permitted. Deterministic and side-effect free:
/// this is a safety rule, so it is unit-tested exhaustively and never delegated to a model.
/// </summary>
internal static class DisclosurePolicy
{
    private static readonly DisclosurePurpose[] TpoPurposes = [DisclosurePurpose.Treatment, DisclosurePurpose.Payment, DisclosurePurpose.HealthCareOperations];

    public static Result Authorize(
        IReadOnlyCollection<SensitivityLabel> labels,
        DisclosureBasis basis,
        DisclosurePurpose purpose,
        Consent? consent,
        DateOnly today,
        bool clientInTreatment)
    {
        ArgumentNullException.ThrowIfNull(labels);

        if (labels.Count == 0)
        {
            return new Error("disclosure.no_records", "Describe the records being disclosed.");
        }

        var counselingNotes = labels.Contains(SensitivityLabel.Part2CounselingNote);
        var part2 = counselingNotes || labels.Contains(SensitivityLabel.Part2);

        if (basis == DisclosureBasis.MedicalEmergency)
        {
            // §2.51 permits disclosure to medical personnel to meet a bona fide medical emergency. Counseling notes are
            // held back: they are not needed to treat an emergency and have the strictest consent rule.
            return counselingNotes
                ? new Error("disclosure.emergency_counseling_notes", "Counseling notes are not disclosed under the medical emergency exception.", ErrorKind.Forbidden)
                : Result.Success();
        }

        if (!part2)
        {
            return Result.Success();
        }

        if (consent is null)
        {
            return new Error("disclosure.consent_required", "Part 2 records need a written consent or a documented medical emergency.", ErrorKind.Forbidden);
        }

        if (!consent.IsEffective(today, clientInTreatment))
        {
            return new Error("disclosure.consent_not_effective", "The selected consent is revoked or expired.", ErrorKind.Forbidden);
        }

        if (counselingNotes && consent.Scope != ConsentScope.CounselingNotes)
        {
            return new Error("disclosure.counseling_notes_consent", "Counseling notes can only be disclosed under a consent specific to counseling notes.", ErrorKind.Forbidden);
        }

        if (!counselingNotes && consent.Scope == ConsentScope.CounselingNotes)
        {
            return new Error("disclosure.wrong_consent", "A counseling-notes consent covers counseling notes only.", ErrorKind.Forbidden);
        }

        if (consent.Scope == ConsentScope.TreatmentPaymentOperations && !TpoPurposes.Contains(purpose))
        {
            return new Error("disclosure.outside_tpo", "A TPO consent covers treatment, payment and health care operations only.", ErrorKind.Forbidden);
        }

        return Result.Success();
    }
}

using CareConnector.Modules.Consent.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.Consent.Domain;

/// <summary>
/// Who inside the program may see a record. Part 2 permits communications within a program to personnel who need
/// the information for treatment (§2.12(c)(3)); that need-to-know is expressed as clinical roles.
/// Counseling notes stay with their author, like HIPAA psychotherapy notes.
/// </summary>
internal static class ReadPolicy
{
    /// <param name="emergency">True when the actor holds emergency access to this record's resident right now.</param>
    public static AccessDecision Decide(ICurrentUser actor, RecordDescriptor record, bool emergency = false)
    {
        ArgumentNullException.ThrowIfNull(actor);
        ArgumentNullException.ThrowIfNull(record);

        if (!actor.Scope.AllowsClient(record.ClientId))
        {
            return AccessDecision.Deny("This resident is outside your assigned facilities.");
        }

        // Emergency access opens what clinical staff see, to a person, for a resident, for a reason on record.
        // It does not open counseling notes and it is never an agent's.
        if (emergency && actor.Kind == ActorKind.Human && record.Label == SensitivityLabel.Part2)
        {
            return AccessDecision.Allow("Emergency access; the reason is on record and it is reviewed.");
        }

        // Explicit human program oversight uses this same gate (§2.12(c)(3)); no agent delegation or
        // counseling-note access accompanies that read-only role, including a matching author ID.
        if (actor.IsInRole(Roles.ProgramViewer))
            return actor.Kind == ActorKind.Human && record.Label is SensitivityLabel.General or SensitivityLabel.Part2
                ? AccessDecision.Allow("Internal program oversight; explicitly approved read-only access.")
                : AccessDecision.Deny("Program viewing does not include counseling notes or agent delegation.");
        if (actor.Agent?.OnBehalfOfRoles.Contains(Roles.ProgramViewer) == true)
            return AccessDecision.Deny("Program viewing cannot be delegated to agents.");

        // Agents read with the roles of the person they act for, and never see counseling notes.
        if (actor.Kind == ActorKind.Agent)
        {
            if (actor.Agent is not { } agent)
            {
                return AccessDecision.Deny("Agent without an accountable person.");
            }

            if (record.Label == SensitivityLabel.Part2CounselingNote)
            {
                return AccessDecision.Deny("Counseling notes are never provided to agents.");
            }

            return Decide(new RolesOnly(agent.OnBehalfOfUserId, agent.OnBehalfOfRoles), record);
        }

        // Direct-care staff observe and document residents, so they have a treatment need for Part 2 records.
        var clinical = actor.IsInRole(Roles.Clinician) || actor.IsInRole(Roles.Supervisor) || actor.IsInRole(Roles.DirectCare);
        return record.Label switch
        {
            SensitivityLabel.General => AccessDecision.Allow("General record; staff access."),
            SensitivityLabel.Part2 when clinical => AccessDecision.Allow("Part 2 record; internal program use for treatment (§2.12(c)(3))."),
            SensitivityLabel.Part2 => AccessDecision.Deny("Part 2 records are limited to clinical staff with a treatment need."),
            SensitivityLabel.Part2CounselingNote when record.AuthorId is not null && record.AuthorId == actor.UserId =>
                AccessDecision.Allow("Counseling note; author access."),
            SensitivityLabel.Part2CounselingNote => AccessDecision.Deny("Counseling notes are available only to their author."),
            _ => AccessDecision.Deny("Unknown sensitivity label."),
        };
    }

    private sealed class RolesOnly(string userId, IReadOnlyCollection<string> roles) : ICurrentUser
    {
        public string UserId => userId;

        public string DisplayName => userId;

        public bool IsInRole(string role) => roles.Contains(role);
    }
}

