        new("therapy", 1, "Clinical therapy and process", "Clinical group documentation by authorized clinical staff.", "Session objective", "Intervention provided", "Individual response and next step", true, true),
        new("recovery", 1, "Recovery support", "Recovery discussion, support or skills practice.", "Recovery topic or objective", "Discussion, exercise or support provided", "Individual participation, response and next step", false, true),
        new("activity", 1, "Recreation and social activity", "An activity, social opportunity or recreation session.", "Purpose of the activity", "Activity offered", "Individual observations or assistance, when relevant", false, false),
        new("community", 1, "Community and life skills", "An outing or practice of an everyday task.", "Task or skill practiced", "Activity and assistance offered", "What the resident did and the support needed", false, true),
    ];

    public static GroupForm? Find(string? key, int version = 1) => All.FirstOrDefault(f => f.Key == key && f.Version == version);

    public static bool CanDocument(GroupForm form, ICurrentUser user) => user.Kind == ActorKind.Human
        && (user.IsInRole(Roles.Supervisor) || user.IsInRole(Roles.Clinician) || (!form.Clinical && user.IsInRole(Roles.DirectCare)));
}

internal sealed class GroupFormApproval : AggregateRoot
{
    private GroupFormApproval() { }
    public string FacilityId { get; private set; } = "";
    public string FormKey { get; private set; } = "";
    public int Version { get; private set; }
    public string FormSnapshot { get; private set; } = "";
    public string ReviewedBy { get; private set; } = "";
    public string ReviewedByName { get; private set; } = "";
    public DateTimeOffset ReviewedAt { get; private set; }
    public bool Active { get; private set; }
    public string? RetiredReason { get; private set; }

    public static Result<GroupFormApproval> Approve(string facility, GroupForm form, ICurrentUser user, DateTimeOffset now)
    {
        if (ActorRules.RequireHuman(user, "Approving a group form") is { } error) return error;
        if (!user.IsInRole(Roles.Supervisor)) return new Error("group.form_review_forbidden", "A supervisor reviews the program's group forms.", ErrorKind.Forbidden);
        return new GroupFormApproval { FacilityId = facility, FormKey = form.Key, Version = form.Version, FormSnapshot = JsonSerializer.Serialize(form), ReviewedBy = user.UserId, ReviewedByName = user.DisplayName, ReviewedAt = now, Active = true };
    }

    public Result Retire(string reason, ICurrentUser user)
    {
        if (ActorRules.RequireHuman(user, "Retiring a group form") is { } error) return error;
        if (!user.IsInRole(Roles.Supervisor)) return new Error("group.form_review_forbidden", "A supervisor reviews the program's group forms.", ErrorKind.Forbidden);
        if (string.IsNullOrWhiteSpace(reason) || reason.Length > 1000) return new Error("group.reason_required", "Say why this form is being retired.");
        Active = false; RetiredReason = reason.Trim(); return Result.Success();
    }
}

internal sealed record GroupIndividualDetails(int? Minutes, string? Support, string? FollowUp, IReadOnlyList<GroupPlanLink> Plans, IReadOnlyList<GroupGoalLink> Goals)
{
    public static GroupIndividualDetails Empty => new(null, null, null, [], []);
    public Error? Check(AttendanceStatus status, string? response, int? duration)
    {
        if (Plans is null || Goals is null || Plans.Count > 10 || Goals.Count > 10 || Plans.Select(p => p.Id).Distinct().Count() != Plans.Count || Goals.Select(g => g.Id).Distinct().Count() != Goals.Count)
            return new Error("group.links_invalid", "Choose up to ten distinct plan items and goals.");
        if (Support?.Length > 2000 || FollowUp?.Length > 2000) return new Error("group.detail_too_long", "Support and next steps are limited to 2,000 characters each.");
        if (Minutes is < 1 or > 480 || (Minutes is not null && duration is not null && Minutes > duration)) return new Error("group.minutes_invalid", "Time present must fit within the group session.");
        if (status is not (AttendanceStatus.Attended or AttendanceStatus.LeftEarly) && (Minutes is not null || Goals.Count > 0))
            return new Error("group.absent_evidence", "Do not record time or goal work for someone who did not attend.");
        if (Goals.Any(g => g.Progress is not (null or "MovedForward" or "NoChange" or "SetBack"))) return new Error("group.progress_invalid", "Choose a supported goal progress observation.");
        if (Goals.Any(g => g.Progress is not null) && string.IsNullOrWhiteSpace(response)) return new Error("group.progress_evidence", "Describe the individual observation supporting goal progress.");
        return null;
    }
}

internal sealed record GroupResidentCorrection(AttendanceStatus Status, string? Note, Participation? Participation, GroupIndividualDetails Details, bool EnteredInError);

internal sealed record GroupResidentAddendum(string Text, string AuthorId, string AuthorName, DateTimeOffset AddedAt, GroupResidentCorrection? Correction);

using System.Text.Json;
using CareConnector.Modules.Consent.Contracts;
using CareConnector.Modules.Groups.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.Groups.Domain;

internal enum SessionStatus
{
    /// <summary>Being documented: attendance and description can change.</summary>
    Open,

    /// <summary>Signed by the facilitator. Immutable; corrections are addenda.</summary>
    Signed,

    /// <summary>Started by mistake or did not take place. Kept with its reason; counts for no one.</summary>
    Cancelled,
}

internal enum AttendanceStatus
{
    /// <summary>Listed as expected; not marked yet.</summary>
    Expected,
    Attended,
    LeftEarly,
    Refused,
    Excused,

    /// <summary>Out of the building or otherwise unavailable.</summary>
    NotHere,

    /// <summary>Listed by mistake; not counted.</summary>
    Removed,
}

/// <summary>How a resident who came took part. Optional: a mark of attendance alone is a complete record.</summary>
internal enum Participation
{
    /// <summary>Spoke up, joined in, did the exercise.</summary>
    Engaged,

    TookPart,

    /// <summary>Present and listening, said little.</summary>
    Quiet,

    /// <summary>Disrupted the group. What happened is written down before the group is signed.</summary>
    Disruptive,
}

internal sealed class SessionAddendum
{
    public required string Text { get; init; }

    public required string AuthorId { get; init; }

    public required string AuthorName { get; init; }

    public required DateTimeOffset AddedAt { get; init; }
}

/// <summary>
/// One group or activity held once. The description is written once for the session; who came, who was expected and
/// did not, and anything particular to one resident live on <see cref="GroupAttendance"/>, one row per resident, so a
/// resident's chart shows only their own line.
/// </summary>
internal sealed class GroupSession : AggregateRoot
{
    /// <summary>A session is documented the day it happens; it cannot be started for an earlier day.</summary>
    public static readonly TimeSpan MaximumBackdate = TimeSpan.FromHours(12);

    private GroupSession()
    {
    }

    public string FacilityId { get; private set; } = "";

    public string GroupName { get; private set; } = "";

    public GroupFamily Family { get; private set; }

    public string? Topic { get; private set; }

    public string? Location { get; private set; }

    public string? Description { get; private set; }

    public DateTimeOffset StartedAt { get; private set; }

    public int? DurationMinutes { get; private set; }

    public string FacilitatorId { get; private set; } = "";

    public string FacilitatorName { get; private set; } = "";

    public SessionStatus Status { get; private set; }

    public DateTimeOffset RecordedAt { get; private set; }

    public DateTimeOffset? SignedAt { get; private set; }

    public List<SessionAddendum> Addenda { get; private set; } = [];

    public string? CancelledReason { get; private set; }

    public int Revision { get; private set; }
    public string? FormKey { get; private set; }
    public int FormVersion { get; private set; }
    public string? FormSnapshot { get; private set; }
    public Guid? FormApprovalId { get; private set; }
    public string? Objective { get; private set; }
    public string? Method { get; private set; }
    public string? SignedByName { get; private set; }
    public GroupForm? Form => FormSnapshot is null ? null : JsonSerializer.Deserialize<GroupForm>(FormSnapshot);

    public Result UseForm(GroupForm form, ICurrentUser user)
    {
        if (CanChange(user) is { } error) return error;
        if (FormKey is not null) return Error.Conflict("group.form_fixed", "The form is fixed when the group starts.");
        if (!GroupForms.CanDocument(form, user)) return new Error("group.form_role", "This group form requires a clinical role.", ErrorKind.Forbidden);
        FormKey = form.Key; FormVersion = form.Version; FormSnapshot = JsonSerializer.Serialize(form); Touch();
        return Result.Success();
    }

    public Result ApproveForm(GroupFormApproval approval, ICurrentUser user)
    {
        if (CanChange(user) is { } error) return error;
        if (!approval.Active || approval.FacilityId != FacilityId || approval.FormKey != FormKey || approval.Version != FormVersion || approval.FormSnapshot != FormSnapshot)
            return new Error("group.form_not_approved", "The program must review this version of the form before signing.");
        FormApprovalId = approval.Id; return Result.Success();
    }

    public Result DescribeStructured(string? objective, string? method, ICurrentUser user)
    {
        if (CanDocumentContent(user) is { } forbidden) return forbidden;
        if (CanChange(user) is { } error) return error;
        if (objective?.Length > 2000 || method?.Length > 4000) return new Error("group.description_too_long", "Keep the objective within 2,000 characters and the method within 4,000.");
        Objective = Clean(objective); Method = Clean(method); Touch(); return Result.Success();
    }

    public Error? CheckRevision(int? expected) => expected is not null && expected != Revision
        ? Error.Conflict("group.changed", "This group changed on another screen. Reload it and review the latest entries.") : null;

    public void Touch() => Revision++;

    public IReadOnlyList<string> Missing(IReadOnlyCollection<GroupAttendance> lines)
    {
        var issues = new List<string>();
        var listed = lines.Where(a => a.Status != AttendanceStatus.Removed).ToList();
        if (string.IsNullOrWhiteSpace(Description)) issues.Add("Session description");
        if (listed.Count == 0) issues.Add("Resident list");
        if (listed.Any(a => a.Status == AttendanceStatus.Expected)) issues.Add("Unmarked attendance");
        if (listed.Any(a => a.Participation == Participation.Disruptive && string.IsNullOrWhiteSpace(a.Note))) issues.Add("Individual observation for disruption");
        if (Form is { } form)
        {
            if (DurationMinutes is null) issues.Add("Session duration");
            if (string.IsNullOrWhiteSpace(Method)) issues.Add(form.MethodPrompt);
            if (form.Key != "activity" && string.IsNullOrWhiteSpace(Objective)) issues.Add(form.ObjectivePrompt);
            if (form.Key == "community" && string.IsNullOrWhiteSpace(Location)) issues.Add("Outing location");
            if (listed.Any(a => a.Came && form.ResponseRequired && string.IsNullOrWhiteSpace(a.Note))) issues.Add("Individual resident responses");
            if (listed.Any(a => a.Status == AttendanceStatus.LeftEarly && a.Details.Minutes is null)) issues.Add("Time present for residents who left early");
            if (listed.Any(a => a.Details.Check(a.Status, a.Note, DurationMinutes) is not null)) issues.Add("Individual time or goal evidence");
        }
        return issues;
    }

    public static Result<GroupSession> Start(
        string facilityId, string groupName, GroupFamily family, string? topic, string? location, string? description, DateTimeOffset? startedAt,
        ICurrentUser facilitator, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(facilitator);
        if (ActorRules.RequireHuman(facilitator, "Documenting a group") is { } humanError)
        {
            return humanError;
        }

        if (string.IsNullOrWhiteSpace(groupName))
        {
            return new Error("group.name_required", "Choose the group.");
        }

        if (groupName.Length > 200 || topic?.Length > 300 || location?.Length > 200 || description?.Length > 8000 || !Enum.IsDefined(family))
            return new Error("group.fields_invalid", "Review the group name, type and session details; one or more fields exceed the allowed length.");
        var started = startedAt ?? now;
        if (started > now.AddMinutes(5))
        {
            return new Error("group.future", "A group cannot be documented before it starts.");
        }

        if (now - started > MaximumBackdate)
        {
            return new Error("group.too_late", $"A group is documented the day it happens (within {MaximumBackdate.TotalHours:0} hours).");
        }

        return new GroupSession
        {
            FacilityId = facilityId,
            GroupName = groupName.Trim(),
            Family = family,
            Topic = Clean(topic),
            Location = Clean(location),
            Description = Clean(description),
            StartedAt = started,
            FacilitatorId = facilitator.UserId,
            FacilitatorName = facilitator.DisplayName,
            Status = SessionStatus.Open,
            RecordedAt = now,
        };
    }

    public Result Describe(string? topic, string? location, string? description, int? durationMinutes, ICurrentUser user)
    {
        if (CanDocumentContent(user) is { } forbidden) return forbidden;
        if (CanChange(user) is { } error)
        {
            return error;
        }

        if (durationMinutes is < 1 or > 480)
        {
            return new Error("group.duration_invalid", "Length is between 1 and 480 minutes.");
        }

        if (topic?.Length > 300 || location?.Length > 200 || description?.Length > 8000)
            return new Error("group.description_too_long", "The group description is limited to 8,000 characters.");
        Touch();
        Topic = Clean(topic);
        Location = Clean(location);
        Description = Clean(description);
        DurationMinutes = durationMinutes;
        return Result.Success();
    }

    /// <summary>Signs the session. Needs a description and a decision for every listed resident; then nothing changes.</summary>
    public Result Sign(IReadOnlyCollection<GroupAttendance> attendance, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(attendance);
        if (CanChange(user) is { } error)
        {
            return error;
        }

        if (user.UserId != FacilitatorId && !user.IsInRole(Roles.Supervisor))
        {
            return new Error("group.sign_forbidden", "The facilitator signs the group, or a supervisor.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(Description))
        {
            return new Error("group.description_required", "Describe what the group covered before signing.");
        }

        var listed = attendance.Where(a => a.Status != AttendanceStatus.Removed).ToList();
        if (listed.Count == 0)
        {
            return new Error("group.no_residents", "List the residents who attended or were expected.");
        }

        if (listed.Count(a => a.Status == AttendanceStatus.Expected) is > 0 and var unmarked)
        {
            return new Error("group.attendance_incomplete", $"{unmarked} resident{(unmarked == 1 ? " is" : "s are")} not marked. Say whether each attended.");
        }

        // A disruption is never just a mark: what happened is on that resident's line.
        if (listed.Count(a => a.Participation == Participation.Disruptive && a.Note is null) is > 0 and var unexplained)
        {
            return new Error("group.disruption_note_required", $"{unexplained} resident{(unexplained == 1 ? " is" : "s are")} marked as disrupting the group. Say what happened on their line.");
        }

        if (Form is { } form)
        {
            if (!GroupForms.CanDocument(form, user)) return new Error("group.form_role", "This group form requires a clinical role.", ErrorKind.Forbidden);
            if (FormApprovalId is null) return new Error("group.form_not_approved", "The program must review this form before signing.");
            if (Missing(attendance) is { Count: > 0 } missing) return new Error("group.documentation_incomplete", "Complete: " + string.Join(", ", missing) + ".");
        }
        Status = SessionStatus.Signed;
        SignedAt = now;
        SignedByName = user.DisplayName;
        Touch();
        Raise(new GroupSessionSigned(
            Id, FacilityId, GroupName, StartedAt,
            listed.Count(a => a.Status is AttendanceStatus.Attended or AttendanceStatus.LeftEarly), listed.Count, now));
        return Result.Success();
    }

    /// <summary>Cancels an open session that was started by mistake or did not take place. A signed session cannot be cancelled.</summary>
    public Result Cancel(string reason, ICurrentUser user)
    {
        if (CanChange(user) is { } error)
        {
            return error;
        }

        if (user.UserId != FacilitatorId && !user.IsInRole(Roles.Supervisor))
        {
            return new Error("group.cancel_forbidden", "The person who started the group cancels it, or a supervisor.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("group.reason_required", "Say why the group is cancelled.");
        }

        if (reason.Length > 500) return new Error("group.reason_too_long", "Keep the cancellation reason within 500 characters.");
        Touch();
        Status = SessionStatus.Cancelled;
        CancelledReason = reason.Trim();
        return Result.Success();
    }

    public Result AddAddendum(string text, ICurrentUser user, DateTimeOffset now)
    {
        if (CanDocumentContent(user) is { } forbidden) return forbidden;
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Adding to a group record") is { } humanError)
        {
            return humanError;
        }

        if (Status != SessionStatus.Signed)
        {
            return Error.Conflict("group.not_signed", "The group is still open; change it directly.");
        }

        if (string.IsNullOrWhiteSpace(text) || text.Length > 4000)
        {
            return new Error("group.addendum_required", "Write the addendum.");
        }

        Touch();
        Addenda = [.. Addenda, new SessionAddendum { Text = text.Trim(), AuthorId = user.UserId, AuthorName = user.DisplayName, AddedAt = now }];
        return Result.Success();
    }

    public Error? CanDocumentContent(ICurrentUser user) => Form is { } form && !GroupForms.CanDocument(form, user)
        ? new Error("group.form_role", "This group form requires a clinical role.", ErrorKind.Forbidden) : null;

    /// <summary>Null when the session can still be changed by this actor.</summary>
    public Error? CanChange(ICurrentUser user)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Documenting a group") is { } humanError)
        {
            return humanError;
        }

        return Status switch
        {
            SessionStatus.Signed => Error.Conflict("group.signed", "This group is signed. Add an addendum to correct it."),
            SessionStatus.Cancelled => Error.Conflict("group.cancelled", "This group was cancelled."),
            _ => null,
        };
    }

    private static string? Clean(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}

/// <summary>One resident's line on one session: whether they came, and anything particular to them.</summary>
internal sealed class GroupAttendance : AggregateRoot
{
    private GroupAttendance()
    {
    }

    public Guid SessionId { get; private set; }

    public Guid ClientId { get; private set; }

    public AttendanceStatus Status { get; private set; }

    public string? Note { get; private set; }

    /// <summary>How they took part, when they came and someone said.</summary>
    public Participation? Participation { get; private set; }

    public string? ResponseByName { get; private set; }

    public DateTimeOffset? ResponseAt { get; private set; }

    public string MarkedBy { get; private set; } = "";

    public string MarkedByName { get; private set; } = "";

    public DateTimeOffset MarkedAt { get; private set; }

    public SensitivityLabel Label { get; private set; }

    public string DetailsJson { get; private set; } = "{}";
    public string AddendaJson { get; private set; } = "[]";
    public GroupIndividualDetails Details => DetailsJson == "{}" ? GroupIndividualDetails.Empty : JsonSerializer.Deserialize<GroupIndividualDetails>(DetailsJson)!;
    public IReadOnlyList<GroupResidentAddendum> Addenda => JsonSerializer.Deserialize<List<GroupResidentAddendum>>(AddendaJson)!;
    public GroupResidentCorrection? Correction => Addenda.LastOrDefault(a => a.Correction is not null)?.Correction;
    public AttendanceStatus EffectiveStatus => Correction?.Status ?? Status;
    public string? EffectiveNote => Correction is { } c ? c.Note : Note;
    public Participation? EffectiveParticipation => Correction is { } c ? c.Participation : Participation;
    public GroupIndividualDetails EffectiveDetails => Correction?.Details ?? Details;
    public bool EnteredInError => Correction?.EnteredInError ?? false;
    public bool Came => !EnteredInError && EffectiveStatus is AttendanceStatus.Attended or AttendanceStatus.LeftEarly;

    public Result Document(GroupSession session, GroupIndividualDetails details, ICurrentUser user)
    {
        if (session.CanChange(user) is { } error) return error;
        if (session.CanDocumentContent(user) is { } forbidden) return forbidden;
        if (details.Check(Status, Note, session.DurationMinutes) is { } invalid) return invalid;
        DetailsJson = JsonSerializer.Serialize(details); session.Touch(); return Result.Success();
    }

    public Result AddAddendum(GroupSession session, string text, GroupResidentCorrection? correction, ICurrentUser user, DateTimeOffset now)
    {
        if (ActorRules.RequireHuman(user, "Correcting a group note") is { } error) return error;
        if (session.CanDocumentContent(user) is { } forbidden) return forbidden;
        if (session.Status != SessionStatus.Signed) return Error.Conflict("group.not_signed", "The group is still open; update its draft.");
        if (string.IsNullOrWhiteSpace(text) || text.Length > 4000) return new Error("group.addendum_required", "Explain the addition or correction, within 4,000 characters.");
        if (correction is not null)
        {
            if (user.UserId != MarkedBy && user.UserId != session.FacilitatorId && !user.IsInRole(Roles.Supervisor))
                return new Error("group.correction_forbidden", "The author, facilitator or a supervisor corrects the recorded facts.", ErrorKind.Forbidden);
            if (correction.Status is AttendanceStatus.Expected or AttendanceStatus.Removed || !Enum.IsDefined(correction.Status)) return new Error("group.correction_status", "Choose a completed attendance status; use entered in error for a mistaken entry.");
            if (correction.Note?.Length > 4000) return new Error("group.note_too_long", "Keep the individual response within 4,000 characters.");
            if (!correction.EnteredInError && correction.Participation == Domain.Participation.Disruptive && string.IsNullOrWhiteSpace(correction.Note))
                return new Error("group.disruption_note_required", "Describe the observed disruption on this resident's line.");
            if (Check(correction.Status, correction.Participation) is { } invalid) return invalid;
            if (correction.Details.Check(correction.Status, correction.Note, session.DurationMinutes) is { } invalidDetails) return invalidDetails;
            if (!correction.EnteredInError && session.Form is { } form && correction.Status is AttendanceStatus.Attended or AttendanceStatus.LeftEarly
                && ((form.ResponseRequired && string.IsNullOrWhiteSpace(correction.Note)) || (correction.Status == AttendanceStatus.LeftEarly && correction.Details.Minutes is null)))
                return new Error("group.correction_incomplete", "Keep the individual response and actual time with the corrected attendance.");
        }
        AddendaJson = JsonSerializer.Serialize(Addenda.Append(new GroupResidentAddendum(text.Trim(), user.UserId, user.DisplayName, now, correction)));
        session.Touch(); return Result.Success();
    }

    public static Result<GroupAttendance> List(
        GroupSession session, Guid clientId, AttendanceStatus status, string? note, SensitivityLabel label, ICurrentUser user, DateTimeOffset now, Participation? participation = null)
    {
        ArgumentNullException.ThrowIfNull(session);
        if (session.CanChange(user) is { } error)
        {
            return error;
        }

        if ((note is not null || participation is not null) && session.CanDocumentContent(user) is { } forbidden) return forbidden;
        if (note?.Length > 4000) return new Error("group.note_too_long", "Keep the individual response within 4,000 characters.");
        if (Check(status, participation) is { } wrong)
        {
            return wrong;
        }

        session.Touch();
        return new GroupAttendance
        {
            SessionId = session.Id,
            ClientId = clientId,
            Status = status,
            Note = string.IsNullOrWhiteSpace(note) ? null : note.Trim(),
            ResponseByName = string.IsNullOrWhiteSpace(note) ? null : user.DisplayName,
            ResponseAt = string.IsNullOrWhiteSpace(note) ? null : now,
            Participation = participation,
            MarkedBy = user.UserId,
            MarkedByName = user.DisplayName,
            MarkedAt = now,
            Label = label,
        };
    }

    /// <summary>Only someone who came took part in any way.</summary>
    private static Error? Check(AttendanceStatus status, Participation? participation) =>
        Enum.IsDefined(status) && (participation is null || (status is AttendanceStatus.Attended or AttendanceStatus.LeftEarly && Enum.IsDefined(participation.Value)))
            ? null
            : new Error("group.participation_not_applicable", "Say how a resident took part only when they came.");

    /// <param name="participation">Null keeps what was said before, so a tap that only marks attendance (from the floor, perhaps sent late) never erases it.</param>
    public Result Mark(GroupSession session, AttendanceStatus status, string? note, ICurrentUser user, DateTimeOffset now, Participation? participation = null, bool clearNote = false, bool clearParticipation = false)
    {
        ArgumentNullException.ThrowIfNull(session);
        if (session.CanChange(user) is { } error)
        {
            return error;
        }

        if ((note is not null || participation is not null) && session.CanDocumentContent(user) is { } forbidden) return forbidden;
        if (note?.Length > 4000) return new Error("group.note_too_long", "Keep the individual response within 4,000 characters.");
        if (Check(status, participation) is { } wrong)
        {
            return wrong;
        }

        if ((clearNote || clearParticipation) && session.CanDocumentContent(user) is { } clearForbidden) return clearForbidden;
        // Someone who did not come took no part, whatever was said before.
        session.Touch();
        Participation = status is AttendanceStatus.Attended or AttendanceStatus.LeftEarly && !clearParticipation ? participation ?? Participation : null;
        Status = status;
        if ((clearNote || note is not null) && Note != (clearNote || string.IsNullOrWhiteSpace(note) ? null : note.Trim()))
        {
            Note = clearNote || string.IsNullOrWhiteSpace(note) ? null : note.Trim();
            ResponseByName = user.DisplayName; ResponseAt = now;
        }
        MarkedBy = user.UserId;
        MarkedByName = user.DisplayName;
        MarkedAt = now;
        return Result.Success();
    }
}

using CareConnector.Modules.Consent.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.History.Domain;

/// <summary>What kind of record was brought over from an earlier system.</summary>
internal enum HistoryKind
{
    Note,
    ServiceSummary,
    Incident,
    Vital,
    Allergy,
    Diagnosis,
    Contact,
    Profile,
}

/// <param name="Data">Remaining source fields as a JSON object, kept so nothing meaningful is lost in the move.</param>
internal sealed record HistoryInput(
    Guid ClientId, string FacilityId, HistoryKind Kind, string ExternalId, DateTimeOffset? OccurredAt, string? Category, string? Author,
    string? Title, string? Text, string? Data);

/// <summary>
/// A record created in an earlier system (e.g. Eldermark) and brought over for reference. It is history, not a
/// CareConnector entry: it was not written, signed or scored here, it is never edited, and screens label it with its
/// source. New documentation is always made in CareConnector's own modules.
/// </summary>
internal sealed class HistoryRecord : AggregateRoot
{
    public const int MaxTextLength = 40_000;

    private HistoryRecord()
    {
    }

    public Guid ClientId { get; private set; }

    public string FacilityId { get; private set; } = "";

    public string Source { get; private set; } = "";

    public HistoryKind Kind { get; private set; }

    /// <summary>The record's id in the source system; with source and kind it identifies the record, so a load can be repeated.</summary>
    public string ExternalId { get; private set; } = "";

    public DateTimeOffset? OccurredAt { get; private set; }

    public string? Category { get; private set; }

    public string? Author { get; private set; }

    public string? Title { get; private set; }

    public string? Text { get; private set; }

    public string? Data { get; private set; }

    public DateTimeOffset ImportedAt { get; private set; }

    public string ImportedBy { get; private set; } = "";

    public SensitivityLabel Label { get; private set; }

    public static Result<HistoryRecord> Import(string source, HistoryInput input, SensitivityLabel label, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(input);
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Importing records") is { } humanError)
        {
            return humanError;
        }

        if (string.IsNullOrWhiteSpace(source) || string.IsNullOrWhiteSpace(input.ExternalId))
        {
            return new Error("history.identity_required", "An imported record needs its source and its id in that source.");
        }

        if (input.OccurredAt > now.AddDays(1))
        {
            return new Error("history.future", "An imported record cannot be dated in the future.");
        }

        return new HistoryRecord
        {
            ClientId = input.ClientId,
            FacilityId = input.FacilityId,
            Source = source.Trim(),
            Kind = input.Kind,
            ExternalId = input.ExternalId.Trim(),
            OccurredAt = input.OccurredAt,
            Category = Clean(input.Category, 200),
            Author = Clean(input.Author, 200),
            Title = Clean(input.Title, 400),
            Text = Clean(input.Text, MaxTextLength),
            Data = string.IsNullOrWhiteSpace(input.Data) ? null : input.Data,
            ImportedAt = now,
            ImportedBy = user.UserId,
            Label = label,
        };
    }

    private static string? Clean(string? value, int max) =>
        string.IsNullOrWhiteSpace(value) ? null : value.Trim() is { } t && t.Length > max ? t[..max] : value.Trim();
}

