internal sealed class SourceArchiveRecord : AggregateRoot
{
    private SourceArchiveRecord() { }
    public Guid ClientId { get; private set; }
    public string FacilityId { get; private set; } = "";
    public string Kind { get; private set; } = "";
    public string SourceId { get; private set; } = "";
    public int Revision { get; private set; }
    public string Checksum { get; private set; } = "";
    public DateOnly? SourceDate { get; private set; }
    public DateTimeOffset FetchedAt { get; private set; }
    public DateTimeOffset ImportedAt { get; private set; }
    public string ImportedBy { get; private set; } = "";
    public string Fields { get; private set; } = "{}";
    public byte[]? Photo { get; private set; }
    public byte[]? AnswersBinary { get; private set; }
    public byte[]? QuestionsBinary { get; private set; }
    public string? ContentType { get; private set; }
    public SensitivityLabel Label { get; private set; }

    internal static readonly IReadOnlyDictionary<string, string[]> AllowedFields = new Dictionary<string, string[]>(StringComparer.Ordinal)
    {
        ["ServicePlan"] = ["Service_Type", "Service_Description", "Provider", "Service_Date", "Effective_Date", "End_Date", "Last_Updated", "Last_Updated_By", "Instructions", "Location", "Equip_Needed", "Minutes_Service", "Day_Sun", "Day_Mon", "Day_Tue", "Day_Wed", "Day_Thr", "Day_Fri", "Day_Sat", "Service_Times", "Service_Time_Sort", "Repeat_Every", "PRN", "On_Hold", "On_Hold_List", "ON_Schedule_Only", "Recurring_Task_Data", "Res_Problem_ID", "Service_Agreement_Note", "Needs_Attention", "Create_Date", "LastMod_Stamp"],
        ["Immunization"] = ["UUID", "Date_Received", "Vaccine_Name", "Manufacturer_Name", "Route", "Injection_Site", "Vaccine_Lot_Number", "Adverse_Reaction", "Administered_By", "Create_Date", "Create_By", "ProductName_ShortDescription", "Declined", "CVX_Code", "Booster", "LastMod_Stamp"],
        ["CareTeam"] = ["Med_Professional_Code", "Role_Code", "Rank", "Create_Date", "LastMod_Stamp", "ProfessionalName", "RoleName", "Phone", "Phone2", "Email"],
        ["Admission"] = ["Admit_Date", "Discharge_Date", "Discharge_Date_Future", "Previous_Living_Status", "Discharge_Reason", "Discharge_To", "Unit_Number", "Initial_Unit", "Create_Date", "LastMod_Stamp"],
        ["Absence"] = ["From_Date", "To_Date", "To_Date_Future", "Reason", "Who_Requested", "Last_Updated", "Last_Updated_By", "Service_On_Hold", "On_Leave", "Hospital_Visit_Location", "Hospital_Visit_Reason", "Hospital_Visit_Outcome", "Hospital_Discharge_Diagnosis", "Create_Date", "Created_By", "Canceled", "LastMod_Stamp"],
        ["RoomMove"] = ["Unit_Number", "Move_In", "Move_Out", "Move_Out_Future", "Facility_Unit", "Is_Second_Occupant", "Move_in_is_Transfer", "Move_out_is_Transfer", "Current_Living", "Physical_Move_In_Date", "Physical_Move_Out_Date", "Create_Date", "LastMod_Stamp"],
        ["Photo"] = ["Picture_ID", "Modify_DateTime", "LastMod_Stamp", "Unavailable"],
        ["ServiceEvent"] = ["Service_Date", "Service_Time", "Actual_Service_Start_Time", "Service_Type", "Service_Description", "Provider", "Employee_ID", "Service_Plan_ID", "Minutes_of_Service_Actual", "Scheduled_Minutes", "Canceled_Code", "Cancellation_Description", "Note", "Needs_Review", "PRN", "LastMod_Stamp"],
        ["Assessment"] = ["Assessment_Type", "Asmt_Type_Description", "Assessment_Date", "Assessment_By", "Last_Updated", "Last_Updated_By", "Assessment_Score", "Locked", "Signed_Date", "Signed_Time", "Signed_By", "Locked_Date", "Locked_Time", "Locked_By", "Reviewed_Date", "Reviewed_Time", "Reviewed_By", "Scheduled_Date", "Most_Recent", "ForSchedulingPurposesOnly", "LastMod_Stamp", "Questions", "Answers", "PayloadStatus"],
    };

    public static Result<SourceArchiveRecord> Receive(Guid clientId, EldermarkArchiveInput input, int revision,
        SensitivityLabel label, ICurrentUser actor, DateTimeOffset now)
    {
        if (actor.Kind == ActorKind.Agent || !(actor.IsInRole(Roles.Supervisor) || actor.IsInRole(Roles.Administrator))
            || (actor.Kind == ActorKind.System && actor.UserId != "system:eldermark-reference-import"))
            return new Error("archive.forbidden", "Source import requires an authorized supervisor or the dedicated import job.", ErrorKind.Forbidden);
        if (clientId == Guid.Empty || string.IsNullOrWhiteSpace(input.FacilityId) || input.FacilityId.Length > 16
            || !(input.Kind == "Immunization" ? Guid.TryParseExact(input.SourceId, "D", out var uuid) && uuid != Guid.Empty && input.SourceId == uuid.ToString("D") : PositiveId(input.SourceId)) || !PositiveId(input.ResidentId) || revision < 1
            || input.Kind is null || !AllowedFields.TryGetValue(input.Kind, out var allowed) || input.Fields is null || input.Fields.Any(x => !allowed.Contains(x.Key, StringComparer.Ordinal))
            || input.FetchedAt > now.AddMinutes(5) || input.FetchedAt < DateTimeOffset.Parse("2026-01-01T00:00:00Z", System.Globalization.CultureInfo.InvariantCulture))
            return new Error("archive.invalid", "Source identity, kind, fields or fetch time are invalid.");
        var fields = new JsonObject(input.Fields.OrderBy(x => x.Key, StringComparer.Ordinal).Select(x => KeyValuePair.Create(x.Key, x.Value?.DeepClone()))).ToJsonString();
        if (Encoding.UTF8.GetByteCount(fields) > 2_000_000)
            return new Error("archive.too_large", "Source record exceeds the supported size.");
        var mime = input.Photo is { } photo ? ImageType(photo) : null;
        var missingPhoto = input.Fields["Unavailable"] is JsonValue missing && missing.TryGetValue<bool>(out var unavailable) && unavailable;
        if (input.Kind == "Photo" ? (missingPhoto ? input.Photo is not null : mime is null || input.Photo!.Length > 512_000) : input.Photo is not null)
            return new Error("archive.photo_invalid", "Only a bounded PNG or JPEG source photo is supported.");
        if (input.AnswersBinary?.Length > 2_000_000 || input.QuestionsBinary?.Length > 2_000_000
            || (input.Kind != "Assessment" && (input.AnswersBinary is not null || input.QuestionsBinary is not null)))
            return new Error("archive.payload_invalid", "Unsupported source assessment payload.");
        var checksum = Hash(Encoding.UTF8.GetBytes($"{clientId}|{input.ResidentId}|{input.SourceDate:yyyy-MM-dd}|{fields}|{Hash(input.Photo)}|{Hash(input.AnswersBinary)}|{Hash(input.QuestionsBinary)}"));
        return new SourceArchiveRecord
        {
            ClientId = clientId, FacilityId = input.FacilityId, Kind = input.Kind, SourceId = input.SourceId,
            Revision = revision, Checksum = checksum, SourceDate = input.SourceDate, Fields = fields,
            Photo = input.Photo?.ToArray(), ContentType = mime, FetchedAt = input.FetchedAt, ImportedAt = now,
            AnswersBinary = input.AnswersBinary?.ToArray(), QuestionsBinary = input.QuestionsBinary?.ToArray(),
            ImportedBy = actor.UserId, Label = label,
        };
    }

    private static string Hash(byte[]? bytes) => bytes is null ? "" : Convert.ToHexStringLower(SHA256.HashData(bytes));
    private static bool PositiveId(string? value) => value is { Length: > 0 and <= 20 } && value.All(char.IsAsciiDigit) && value[0] != '0';
    private static string? ImageType(byte[] bytes) => bytes.AsSpan().StartsWith(new byte[] { 137, 80, 78, 71, 13, 10, 26, 10 }) ? "image/png"
        : bytes.Length >= 3 && bytes[0] == 255 && bytes[1] == 216 && bytes[2] == 255 ? "image/jpeg" : null;
}

using CareConnector.Modules.Consent.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.ServiceDelivery.Domain;

internal enum DailyLiving
{
    Independent,
    NeedsReminders,
    NeedsHelp,
    NotKeepingUp,
}

/// <summary>What the resident and staff report about taking medication. Epic holds the medication record itself.</summary>
internal enum MedicationReport
{
    Taking,
    MissingSome,
    Refusing,
    NotDiscussed,
}

internal enum MilieuPresence
{
    Engaged,
    KeepsToSelf,
    Isolating,
    InConflict,
}

[Flags]
internal enum CheckInTopics
{
    None = 0,
    Family = 1,
    WorkOrSchool = 2,
    SubstanceUse = 4,
    Legal = 8,
    Benefits = 16,
    Appointments = 32,
    Housing = 64,
    Safety = 128,
}

internal sealed record CheckInInput(
    DailyLiving DailyLiving, MedicationReport Medication, MilieuPresence Milieu, CheckInTopics Topics, string? ResidentWords, string? Progress, string? NextSteps);

/// <summary>
/// A case manager's regular check-in with a resident: the things the old free-text note covered every time, as
/// choices, with writing only where something is worth saying. Immutable once recorded; corrected by marking it
/// entered in error and recording again.
/// </summary>
internal sealed class CheckIn : AggregateRoot
{
    /// <summary>A resident is due a check-in this many days after the last one.</summary>
    public const int DueAfterDays = 7;

    private CheckIn()
    {
    }

    public Guid ClientId { get; private set; }

    public string FacilityId { get; private set; } = "";

    public DailyLiving DailyLiving { get; private set; }

    public MedicationReport Medication { get; private set; }

    public MilieuPresence Milieu { get; private set; }

    public CheckInTopics Topics { get; private set; }

    public string? ResidentWords { get; private set; }

    public string? Progress { get; private set; }

    public string? NextSteps { get; private set; }

    public DateTimeOffset RecordedAt { get; private set; }

    public string RecordedBy { get; private set; } = "";

    public string RecordedByName { get; private set; } = "";

    public DeliveryStatus Status { get; private set; }

    public string? EnteredInErrorReason { get; private set; }

    public SensitivityLabel Label { get; private set; }

    public static Result<CheckIn> Record(Guid clientId, string facilityId, CheckInInput input, SensitivityLabel label, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(input);
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Recording a check-in") is { } humanError)
        {
            return humanError;
        }

        if (!Enum.IsDefined(input.DailyLiving) || !Enum.IsDefined(input.Medication) || !Enum.IsDefined(input.Milieu))
        {
            return new Error("checkin.choices_required", "Choose daily living, medication and time with others.");
        }

        // A safety concern is never just a ticked box: what was said and what happens next are written down.
        if (input.Topics.HasFlag(CheckInTopics.Safety) && (string.IsNullOrWhiteSpace(input.Progress) || string.IsNullOrWhiteSpace(input.NextSteps)))
        {
            return new Error("checkin.safety_detail_required", "A safety concern needs what was discussed and the next steps written down.");
        }

        return new CheckIn
        {
            ClientId = clientId,
            FacilityId = facilityId,
            DailyLiving = input.DailyLiving,
            Medication = input.Medication,
            Milieu = input.Milieu,
            Topics = input.Topics,
            ResidentWords = Clean(input.ResidentWords),
            Progress = Clean(input.Progress),
            NextSteps = Clean(input.NextSteps),
            RecordedAt = now,
            RecordedBy = user.UserId,
            RecordedByName = user.DisplayName,
            Status = DeliveryStatus.Final,
            Label = label,
        };
    }

    public Result MarkEnteredInError(string reason, ICurrentUser user)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (Status == DeliveryStatus.EnteredInError)
        {
            return Error.Conflict("checkin.already_entered_in_error", "Already marked entered in error.");
        }

        if (user.UserId != RecordedBy && !user.IsInRole(Roles.Supervisor))
        {
            return new Error("checkin.correction_forbidden", "Only the person who recorded it or a supervisor can correct it.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("checkin.reason_required", "A reason is required.");
        }

        Status = DeliveryStatus.EnteredInError;
        EnteredInErrorReason = reason.Trim();
        return Result.Success();
    }

    private static string? Clean(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}

using System.Text.Json;
using CareConnector.Modules.Consent.Contracts;
using CareConnector.Modules.ServiceDelivery.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.ServiceDelivery.Domain;

internal enum DocumentStatus
{
    /// <summary>Being written. Only its author sees what it says.</summary>
    Draft,

    /// <summary>Signed by its author. Never edited again; only addenda are added.</summary>
    Signed,

    /// <summary>A draft its author gave up on. Kept, with the reason.</summary>
    Discarded,

    /// <summary>Signed, then found to be wrong (the wrong resident, say). Kept and marked.</summary>
    EnteredInError,
}

/// <summary>Something added to a signed record afterwards. Dated and attributed; the record itself does not change.</summary>
internal sealed record Addendum(Guid Id, string Text, string By, string ByName, DateTimeOffset At);

/// <summary>
/// A written record of a service: the one type every service that needs writing uses. It is started in one step,
/// saved as it is typed, guided by the sections of its kind, and signed by the person who wrote it. Signing is
/// refused while a required section is empty. Once signed it is never edited; an addendum is added instead.
/// </summary>
internal sealed class Document : AggregateRoot
{
    public const int MaxSectionLength = 4000;
    public const int MaxAddendumLength = 4000;

    /// <summary>
    /// A record signed, or still unsigned, this long after what it describes is counted as late in reports.
    /// A working figure until program leads set their own; nothing is refused because of it.
    /// </summary>
    public static readonly TimeSpan LateAfter = TimeSpan.FromHours(24);

    private Document()
    {
    }

    public Guid ClientId { get; private set; }

    public string FacilityId { get; private set; } = "";

    public string KindCode { get; private set; } = "";

    public string KindName { get; private set; } = "";

    public string ServiceCode { get; private set; } = "";

    public string ServiceName { get; private set; } = "";

    /// <summary>When the thing being written about happened, as the author gave it.</summary>
    public DateTimeOffset OccurredAt { get; private set; }

    /// <summary>The answers by section key, as JSON. A section with several choices holds them one per line.</summary>
    public string Content { get; private set; } = "{}";

    /// <summary>
    /// Counted by the tablet the author is writing on: each save carries a higher number than the last, so a save
    /// that arrives late or twice never overwrites newer writing.
    /// </summary>
    public int Revision { get; private set; }

    public DocumentStatus Status { get; private set; }

    public string AuthorId { get; private set; } = "";

    public string AuthorName { get; private set; } = "";

    public DateTimeOffset StartedAt { get; private set; }

    public DateTimeOffset SavedAt { get; private set; }

    public DateTimeOffset? SignedAt { get; private set; }

    /// <summary>Why a draft was discarded or a signed record marked entered in error.</summary>
    public string? ClosedReason { get; private set; }

    public string? ClosedByName { get; private set; }

    /// <summary>The addenda, oldest first, as JSON.</summary>
    public string AddendaJson { get; private set; } = "[]";

    /// <summary>The goals this record is about and how the work bore on each, as JSON.</summary>
    public string GoalsJson { get; private set; } = "[]";

    public IReadOnlyList<GoalMark> Goals => JsonSerializer.Deserialize<List<GoalMark>>(GoalsJson) ?? [];

    public SensitivityLabel Label { get; private set; }

    public IReadOnlyDictionary<string, string> Answers => JsonSerializer.Deserialize<Dictionary<string, string>>(Content) ?? [];

    public IReadOnlyList<Addendum> Addenda => JsonSerializer.Deserialize<List<Addendum>>(AddendaJson) ?? [];

    /// <summary>
    /// Starts a draft. The id is made on the tablet, so a record can be started with no connection and sent later
    /// without ever becoming two.
    /// </summary>
    public static Result<Document> Start(
        Guid id, Guid clientId, string facilityId, string kindCode, string serviceName, DateTimeOffset? occurredAt, IReadOnlyDictionary<string, string>? answers, int revision,
        SensitivityLabel label, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Writing a record") is { } humanError)
        {
            return humanError;
        }

        if (id == Guid.Empty)
        {
            return new Error("document.id_required", "The record has no id.");
        }

        if (DocumentKinds.Find(kindCode) is not { } kind)
        {
            return new Error("document.kind_unknown", "Choose what kind of record this is.");
        }

        if (!kind.MayWrite(user))
        {
            return new Error("document.kind_forbidden", $"A {kind.Name.ToLowerInvariant()} is written by a clinician or supervisor.", ErrorKind.Forbidden);
        }

        var when = Occurred(occurredAt, now);
        if (!when.IsSuccess)
        {
            return when.Error!;
        }

        var cleaned = Clean(kind, answers ?? new Dictionary<string, string>());
        if (!cleaned.IsSuccess)
        {
            return cleaned.Error!;
        }

        return new Document
        {
            Id = id,
            ClientId = clientId,
            FacilityId = facilityId,
            KindCode = kind.Code,
            KindName = kind.Name,
            ServiceCode = kind.ServiceCode,
            ServiceName = serviceName,
            OccurredAt = when.Value,
            Content = JsonSerializer.Serialize(cleaned.Value),
            Revision = Math.Max(1, revision),
            Status = DocumentStatus.Draft,
            AuthorId = user.UserId,
            AuthorName = user.DisplayName,
            StartedAt = now,
            SavedAt = now,
            Label = label,
        };
    }

    /// <summary>
    /// Saves the draft as typed. Returns false, changing nothing, when this save is not newer than what is already
    /// held: it arrived late or twice.
    /// </summary>
    public Result<bool> Save(IReadOnlyDictionary<string, string> answers, DateTimeOffset? occurredAt, int revision, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(answers);
        if (Writable(user) is { } error)
        {
            return error;
        }

        if (revision <= Revision)
        {
            return false;
        }

        var cleaned = Clean(Kind, answers);
        if (!cleaned.IsSuccess)
        {
            return cleaned.Error!;
        }

        if (occurredAt is not null)
        {
            var when = Occurred(occurredAt, now);
            if (!when.IsSuccess)
            {
                return when.Error!;
            }

            OccurredAt = when.Value;
        }

        Content = JsonSerializer.Serialize(cleaned.Value);
        Revision = revision;
        SavedAt = now;
        return true;
    }

    /// <summary>
    /// Says which of the resident's goals this record is about, and how the work bore on each. Only the author, only
    /// while it is a draft, only for a kind of record that points at goals, and only goals that are this
    /// resident's and still active. Replaces what was said before.
    /// </summary>
    /// <param name="active">The resident's active goals: id and the goal's words.</param>
    public Result PointAt(IReadOnlyList<(Guid GoalId, GoalProgress Progress)> marks, IReadOnlyDictionary<Guid, string> active, ICurrentUser user)
    {
        ArgumentNullException.ThrowIfNull(marks);
        ArgumentNullException.ThrowIfNull(active);
        if (Writable(user) is { } error)
        {
            return error;
        }

        if (marks.Count > 0 && !Kind.PointsAtGoals)
        {
            return new Error("document.goals_not_applicable", $"A {KindName.ToLowerInvariant()} does not point at goals.");
        }

        if (marks.Select(m => m.GoalId).Distinct().Count() != marks.Count || marks.Any(m => !Enum.IsDefined(m.Progress)))
        {
            return new Error("document.goal_progress_required", "Say once for each goal how it went.");
        }

        // A goal already on this draft keeps its place if it was closed while the draft was open.
        var already = Goals.ToDictionary(g => g.GoalId, g => g.Statement);
        if (marks.Any(m => !active.ContainsKey(m.GoalId) && !already.ContainsKey(m.GoalId)))
        {
            return new Error("document.goal_unknown", "One of those is not an active goal of this resident.");
        }

        GoalsJson = JsonSerializer.Serialize(marks.Select(m => new GoalMark(m.GoalId, active.GetValueOrDefault(m.GoalId) ?? already[m.GoalId], m.Progress)));
        return Result.Success();
    }

    /// <summary>How long from what happened to the signature, or to now while it is unsigned. Null for a closed record.</summary>
    public TimeSpan? Waited(DateTimeOffset now) => Status switch
    {
        DocumentStatus.Signed => SignedAt - OccurredAt,
        DocumentStatus.Draft => now - OccurredAt,
        _ => null,
    };

    public bool IsLate(DateTimeOffset now) => Waited(now) > LateAfter;

    /// <summary>The titles of the required sections still empty. Fixed rules: nothing here judges what was written.</summary>
    public IReadOnlyList<string> Missing()
    {
        var answers = Answers;
        return Kind.Sections.Where(s => IsRequired(s, answers) && string.IsNullOrWhiteSpace(answers.GetValueOrDefault(s.Key))).Select(s => s.Title).ToList();
    }

    /// <summary>The author attests to the record. From here it does not change.</summary>
    public Result Sign(ICurrentUser user, DateTimeOffset now)
    {
        if (Writable(user) is { } error)
        {
            return error;
        }

        if (ActorRules.RequireHuman(user, "Signing a record") is { } humanError)
        {
            return humanError;
        }

        var missing = Missing();
        if (missing.Count > 0)
        {
            return new Error("document.incomplete", $"Still needed before signing: {string.Join("; ", missing)}.");
        }

        Status = DocumentStatus.Signed;
        SignedAt = now;
        Raise(new DocumentSigned(Id, ClientId, FacilityId, KindCode, ServiceCode, now));
        return Result.Success();
    }

    /// <summary>Adds to a signed record. Anyone who may write records may add one; it carries their name and the time.</summary>
    public Result<Addendum> AddAddendum(string? text, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Adding an addendum") is { } humanError)
        {
            return humanError;
        }

        if (Status != DocumentStatus.Signed)
        {
            return Error.Conflict("document.not_signed", Status == DocumentStatus.Draft ? "This record is not signed yet: edit it instead." : "This record is closed.");
        }

        if (string.IsNullOrWhiteSpace(text))
        {
            return new Error("document.addendum_empty", "Write what you are adding.");
        }

        if (text.Trim().Length > MaxAddendumLength)
        {
            return new Error("document.too_long", $"An addendum can be {MaxAddendumLength:N0} characters at most.");
        }

        var addendum = new Addendum(Guid.CreateVersion7(), text.Trim(), user.UserId, user.DisplayName, now);
        AddendaJson = JsonSerializer.Serialize(Addenda.Append(addendum));
        return addendum;
    }

    /// <summary>The author gives up on a draft. It is kept, closed, with the reason.</summary>
    public Result Discard(string? reason, ICurrentUser user)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (Status != DocumentStatus.Draft)
        {
            return Error.Conflict("document.not_draft", "Only a draft can be discarded. A signed record is marked entered in error.");
        }

        return Close(DocumentStatus.Discarded, reason, user);
    }

    public Result MarkEnteredInError(string? reason, ICurrentUser user)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (Status != DocumentStatus.Signed)
        {
            return Error.Conflict("document.not_signed", "Only a signed record can be marked entered in error.");
        }

        return Close(DocumentStatus.EnteredInError, reason, user);
    }

    private DocumentKind Kind => DocumentKinds.Find(KindCode) ?? throw new InvalidOperationException($"Unknown record kind {KindCode}.");

    private static bool IsRequired(DocumentSection section, IReadOnlyDictionary<string, string> answers) =>
        section.Required
        || (section.RequiredUnless is { } unless && answers.GetValueOrDefault(unless.Key) is { Length: > 0 } answer && !string.Equals(answer, unless.Answer, StringComparison.Ordinal))
        || (section.RequiredWhen is { } when && (answers.GetValueOrDefault(when.Key) ?? "").Split('\n').Contains(when.Answer));

    /// <summary>What happened cannot be in the future, and a record is not started for something long past.</summary>
    private static Result<DateTimeOffset> Occurred(DateTimeOffset? occurredAt, DateTimeOffset now)
    {
        var when = occurredAt ?? now;
        if (when > now.AddMinutes(5))
        {
            return new Error("document.occurred_future", "The time it happened cannot be in the future.");
        }

        if (when < now.AddDays(-7))
        {
            return new Error("document.occurred_too_old", "Something more than a week ago needs a supervisor to record it.");
        }

        return when;
    }

    /// <summary>Keeps only this kind's sections, trimmed; a choice must be one of the choices.</summary>
    private static Result<Dictionary<string, string>> Clean(DocumentKind kind, IReadOnlyDictionary<string, string> answers)
    {
        var cleaned = new Dictionary<string, string>();
        foreach (var (key, raw) in answers)
        {
            if (kind.Sections.FirstOrDefault(s => s.Key == key) is not { } section)
            {
                return new Error("document.section_unknown", $"This kind of record has no section \"{key}\".");
            }

            var value = (raw ?? "").Trim();
            if (value.Length == 0)
            {
                continue;
            }

            if (value.Length > MaxSectionLength)
            {
                return new Error("document.too_long", $"\"{section.Title}\" can be {MaxSectionLength:N0} characters at most.");
            }

            if (section.Type != SectionType.Text)
            {
                var chosen = value.Split('\n', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries).Distinct().ToList();
                if (chosen.Any(c => !section.Options.Contains(c)) || (section.Type == SectionType.Choice && chosen.Count > 1))
                {
                    return new Error("document.choice_unknown", $"\"{section.Title}\" has an answer that is not one of its choices.");
                }

                // Kept in the order the choices are listed, whatever order they were tapped in.
                value = string.Join('\n', section.Options.Where(chosen.Contains));
            }

            cleaned[key] = value;
        }

        return cleaned;
    }

    private Error? Writable(ICurrentUser user)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (Status != DocumentStatus.Draft)
        {
            return Error.Conflict("document.not_draft", Status == DocumentStatus.Signed ? "This record is signed. Add an addendum instead." : "This record is closed.");
        }

        return user.UserId == AuthorId ? null : new Error("document.not_author", $"This is {AuthorName}'s draft. Only they can change or sign it.", ErrorKind.Forbidden);
    }

    private Result Close(DocumentStatus status, string? reason, ICurrentUser user)
    {
        if (user.UserId != AuthorId && !user.IsInRole(Roles.Supervisor))
        {
            return new Error("document.close_forbidden", "Only the person who wrote it or a supervisor can do that.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("document.reason_required", "A reason is required.");
        }

        Status = status;
        ClosedReason = reason.Trim();
        ClosedByName = user.DisplayName;
        return Result.Success();
    }
}

