using CareConnector.Modules.Consent.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.ServiceDelivery.Domain;

/// <summary>The part of a resident's life a goal is about. The same areas a one-to-one session can be about.</summary>
internal enum GoalArea
{
    MoodOrCoping,
    SubstanceUseOrRecovery,
    DailyLiving,
    RelationshipsOrFamily,
    HousingOrDischarge,
    WorkSchoolOrBenefits,
    HealthOrMedication,
    Safety,
    Other,
}

internal enum GoalStatus
{
    Active,

    /// <summary>The resident got there.</summary>
    Met,

    /// <summary>Replaced by a goal that says it better, or is no longer what the resident is working on.</summary>
    Changed,

    /// <summary>Stopped without being met.</summary>
    Stopped,
}

/// <summary>How a piece of work bore on a goal, as the person writing it up saw it.</summary>
internal enum GoalProgress
{
    MovedForward,
    NoChange,
    SetBack,
}

/// <summary>A written record pointing at a goal. It carries the goal's words as they were, so the record reads the same after the goal is closed.</summary>
internal sealed record GoalMark(Guid GoalId, string Statement, GoalProgress Progress);

/// <summary>
/// Something a resident is working toward, in words they would recognise, with what staff do to help. Written
/// records point at goals, which is what lets anyone see whether the work is getting the resident anywhere.
/// A goal is not reworded once set: it is closed (met, changed or stopped, with a reason) and a new one is set,
/// so the history of what was being worked on is never rewritten.
/// </summary>
internal sealed class Goal : AggregateRoot
{
    public const int MaxStatement = 500;
    public const int MaxHelp = 1000;

    private Goal()
    {
    }

    public Guid ClientId { get; private set; }

    public string FacilityId { get; private set; } = "";

    public GoalArea Area { get; private set; }

    /// <summary>The goal, as the resident would say it.</summary>
    public string Statement { get; private set; } = "";

    /// <summary>What staff do to help.</summary>
    public string? Help { get; private set; }

    public DateOnly? TargetDate { get; private set; }

    public GoalStatus Status { get; private set; }

    public string SetBy { get; private set; } = "";

    public string SetByName { get; private set; } = "";

    public DateTimeOffset SetAt { get; private set; }

    public string? ClosedReason { get; private set; }

    public string? ClosedByName { get; private set; }

    public DateTimeOffset? ClosedAt { get; private set; }

    public SensitivityLabel Label { get; private set; }

    public static Result<Goal> Set(
        Guid clientId, string facilityId, GoalArea area, string? statement, string? help, DateOnly? targetDate, SensitivityLabel label, ICurrentUser user, DateTimeOffset now,
        DateOnly today)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Setting a goal") is { } humanError)
        {
            return humanError;
        }

        if (!MayPlan(user))
        {
            return new Error("goal.forbidden", "A clinician or supervisor sets a resident's goals.", ErrorKind.Forbidden);
        }

        if (!Enum.IsDefined(area))
        {
            return new Error("goal.area_required", "Choose what the goal is about.");
        }

        if (string.IsNullOrWhiteSpace(statement))
        {
            return new Error("goal.statement_required", "Write the goal, in words the resident would recognise.");
        }

        if (statement.Trim().Length > MaxStatement || (help?.Trim().Length ?? 0) > MaxHelp)
        {
            return new Error("goal.too_long", $"A goal can be {MaxStatement} characters and what staff do {MaxHelp:N0} at most.");
        }

        if (targetDate is { } target && target < today)
        {
            return new Error("goal.target_past", "The target date has already passed.");
        }

        return new Goal
        {
            ClientId = clientId,
            FacilityId = facilityId,
            Area = area,
            Statement = statement.Trim(),
            Help = string.IsNullOrWhiteSpace(help) ? null : help.Trim(),
            TargetDate = targetDate,
            Status = GoalStatus.Active,
            SetBy = user.UserId,
            SetByName = user.DisplayName,
            SetAt = now,
            Label = label,
        };
    }

    /// <summary>Closes the goal: met, changed or stopped, and why. It stays on the record.</summary>
    public Result Close(GoalStatus outcome, string? reason, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (!MayPlan(user))
        {
            return new Error("goal.forbidden", "A clinician or supervisor closes a resident's goals.", ErrorKind.Forbidden);
        }

        if (Status != GoalStatus.Active)
        {
            return Error.Conflict("goal.already_closed", "This goal is already closed.");
        }

        if (outcome is not (GoalStatus.Met or GoalStatus.Changed or GoalStatus.Stopped))
        {
            return new Error("goal.outcome_required", "Say whether the goal was met, changed or stopped.");
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("goal.reason_required", "Say what happened: how it was met, or why it changed or stopped.");
        }

        Status = outcome;
        ClosedReason = reason.Trim();
        ClosedByName = user.DisplayName;
        ClosedAt = now;
        return Result.Success();
    }

    private static bool MayPlan(ICurrentUser user) => user.IsInRole(Roles.Clinician) || user.IsInRole(Roles.Supervisor);
}

using System.Text.Json;
using CareConnector.Modules.Consent.Contracts;
