namespace CareConnector.Modules.ServiceDelivery.Domain;

internal sealed class IncidentReport : AggregateRoot
{
    private IncidentReport() { }
    public Guid ClientId { get; private set; }
    public string FacilityId { get; private set; } = "";
    public string FileName { get; private set; } = "";
    public string ContentType { get; private set; } = "";
    public string Checksum { get; private set; } = "";
    public long ByteLength { get; private set; }
    public string Extraction { get; private set; } = "";
    public string SourceJson { get; private set; } = "{}";
    public string ReviewJson { get; private set; } = "{}";
    public string Status { get; private set; } = "NeedsReview";
    public int Revision { get; private set; }
    public string UploadedBy { get; private set; } = "";
    public string UploadedByName { get; private set; } = "";
    public DateTimeOffset UploadedAt { get; private set; }
    public DateTimeOffset UpdatedAt { get; private set; }
    public DateTimeOffset? ConfirmedAt { get; private set; }
    public string? ConfirmedByName { get; private set; }
    public string? ErrorReason { get; private set; }
    public SensitivityLabel Label { get; private set; }

    public static Result<IncidentReport> Receive(Guid id, Guid clientId, string facilityId, string fileName, string contentType,
        string checksum, long length, string extraction, IReadOnlyDictionary<string, string> source, SensitivityLabel label, ICurrentUser user, DateTimeOffset now)
    {
        if (ActorRules.RequireHuman(user, "Uploading an incident report") is { } human) return human;
        if (id == Guid.Empty || clientId == Guid.Empty || length is <= 0 or > 20971520 || fileName.Length > 200)
            return new Error("incident.file", "Choose a report of up to 20 MB and a resident.");
        if (Lic624.Validate(source) is { } invalid) return new Error("incident.form", invalid);
        return new IncidentReport { Id = id, ClientId = clientId, FacilityId = facilityId, FileName = fileName,
            ContentType = contentType, Checksum = checksum, ByteLength = length, Extraction = extraction,
            SourceJson = JsonSerializer.Serialize(source), ReviewJson = JsonSerializer.Serialize(source),
            Status = extraction == "FillablePdf" ? "NeedsReview" : "NeedsTranscription", Label = label,
            UploadedBy = user.UserId, UploadedByName = user.DisplayName, UploadedAt = now, UpdatedAt = now };
    }

    /// <summary>Native initial facts, with no uploaded attachment. SourceJson preserves the first saved statement.</summary>
    public static Result<IncidentReport> Start(Guid id, Guid clientId, string facilityId,
        IReadOnlyDictionary<string, string> data, SensitivityLabel label, ICurrentUser user, DateTimeOffset now)
    {
        if (ActorRules.RequireHuman(user, "Reporting an incident") is { } human) return human;
        if (id == Guid.Empty || clientId == Guid.Empty || string.IsNullOrWhiteSpace(facilityId)) return new Error("incident.resident", "Choose a resident and facility.");
        if (Lic624.Validate(data) is { } invalid) return new Error("incident.form", invalid);
        var clean = data.ToDictionary(p => p.Key, p => (p.Value ?? "").Trim(), StringComparer.Ordinal);
        return new IncidentReport { Id = id, ClientId = clientId, FacilityId = facilityId, FileName = "Incident report",
            ContentType = "application/json", Checksum = id.ToString("N"), Extraction = "DirectEntry", ByteLength = 0,
            SourceJson = JsonSerializer.Serialize(clean), ReviewJson = JsonSerializer.Serialize(clean), Status = "Draft", Label = label,
            UploadedBy = user.UserId, UploadedByName = user.DisplayName, UploadedAt = now, UpdatedAt = now };
    }

    public Result Submit(int expectedRevision, ICurrentUser user, DateTimeOffset now)
    {
        if (ActorRules.RequireHuman(user, "Submitting an incident") is { } human) return human;
        if (!CanEdit(user)) return new Error("incident.forbidden", "Only the author or an authorized reviewer can submit this report.", ErrorKind.Forbidden);
        if (Extraction != "DirectEntry") return Error.Conflict("incident.source", "Uploaded forms already enter the review workflow.");
        if (Status != "Draft" || Revision != expectedRevision) return Error.Conflict("incident.conflict", "Reload the saved report before submitting.");
        var data = Data();
        var required = new[] { "people.0.name", "people.0.date", "eventNarrative", "immediateAction" };
        if (required.Any(key => string.IsNullOrWhiteSpace(data.GetValueOrDefault(key))))
            return new Error("incident.initial_facts", "Record the resident, date occurred, what happened (including time and location), and immediate actions before submitting.");
        Status = "NeedsReview"; Revision++; UpdatedAt = now;
        return Result.Success();
    }

    public Result Review(IReadOnlyDictionary<string, string> data, int expectedRevision, bool confirm, ICurrentUser user, DateTimeOffset now)
    {
        if (ActorRules.RequireHuman(user, "Reviewing an incident") is { } human) return human;
        if (Status is "Confirmed" or "EnteredInError") return Error.Conflict("incident.final", "Confirmed reports cannot be edited. Add a correction or mark the report entered in error.");
        if (Revision != expectedRevision) return Error.Conflict("incident.conflict", "Someone changed this report. Reload before saving; your changes have not been applied.");
        if (!CanEdit(user)) return new Error("incident.forbidden", "Only the uploader or a clinician or supervisor can review this report.", ErrorKind.Forbidden);
        if (confirm && Status == "Draft") return Error.Conflict("incident.draft", "Submit the initial report for review before confirmation.");
        if (confirm && !CanConfirm(user)) return new Error("incident.confirm_forbidden", "A clinician or supervisor must confirm the report.", ErrorKind.Forbidden);
        if (Lic624.Validate(data) is { } invalid) return new Error("incident.form", invalid);
        var clean = data.ToDictionary(p => p.Key, p => (p.Value ?? "").Trim(), StringComparer.Ordinal);
        if (confirm && Lic624.Missing(clean) is { Count: > 0 } missing) return new Error("incident.incomplete", "Complete: " + string.Join(", ", missing));
        ReviewJson = JsonSerializer.Serialize(clean);
        Status = confirm ? "Confirmed" : Status == "Draft" ? "Draft" : "NeedsReview";
        Revision++; UpdatedAt = now;
        if (confirm) { ConfirmedAt = now; ConfirmedByName = user.DisplayName; }
        return Result.Success();
    }

    public Result Correct(string text, int expectedRevision, bool enteredInError, ICurrentUser user, DateTimeOffset now)
    {
        if (ActorRules.RequireHuman(user, "Correcting an incident") is { } human) return human;
        if (!CanEdit(user)) return new Error("incident.forbidden", "Only the uploader or a clinician or supervisor can correct this report.", ErrorKind.Forbidden);
        if (Revision != expectedRevision) return Error.Conflict("incident.conflict", "Reload the report before recording this correction.");
        if (Status == "EnteredInError" || (!enteredInError && Status != "Confirmed")) return Error.Conflict("incident.correction", "Only confirmed reports accept addenda; closed reports cannot be changed.");
        if (string.IsNullOrWhiteSpace(text) || text.Length > 8000) return new Error("incident.reason", "Enter a correction or reason of up to 8,000 characters.");
        if (enteredInError) { Status = "EnteredInError"; ErrorReason = text.Trim(); }
        Revision++; UpdatedAt = now;
        return Result.Success();
    }

    public bool CanEdit(ICurrentUser user) => user.UserId == UploadedBy || CanConfirm(user);
    public static bool CanConfirm(ICurrentUser user) => user.IsInRole(Roles.Clinician) || user.IsInRole(Roles.Supervisor);
    public Dictionary<string, string> Data() => JsonSerializer.Deserialize<Dictionary<string, string>>(ReviewJson) ?? [];
}

/// <summary>Append-only form revisions and corrections, saved atomically with their report and audit entries.</summary>
internal sealed class IncidentRevision : AggregateRoot
{
    private IncidentRevision() { }
    public Guid ReportId { get; private set; }
