namespace CareConnector.Modules.ServiceDelivery.Domain;

internal sealed record IncidentField(string Key, string Label, string Section, string Kind = "text", int Maximum = 500, string? PdfName = null, int Lines = 1);

/// <summary>LIC 624 (4/99). Field mapping matches the Platform's fillable-PDF intake. No reporting deadlines are inferred.</summary>
internal static class Lic624
{
    public const string Source = "https://www.cdss.ca.gov/cdssweb/entres/forms/English/LIC624.PDF";
    public static readonly IReadOnlyList<IncidentField> Fields = Define();
    private static readonly HashSet<string> Keys = Fields.Select(f => f.Key).ToHashSet(StringComparer.Ordinal);

    public static IReadOnlyList<string> Missing(IReadOnlyDictionary<string, string> data)
    {
        var missing = new List<string>();
        foreach (var key in new[] { "facility.name", "facility.fileNumber", "eventNarrative", "immediateAction", "submission.submittedBy", "submission.submittedDate", "submission.reviewedBy", "submission.reviewedDate" })
            if (string.IsNullOrWhiteSpace(data.GetValueOrDefault(key))) missing.Add(Fields.First(f => f.Key == key).Label);
        if (!Enumerable.Range(0, 4).Any(i => !string.IsNullOrWhiteSpace(data.GetValueOrDefault($"people.{i}.name")) && !string.IsNullOrWhiteSpace(data.GetValueOrDefault($"people.{i}.date"))))
            missing.Add("Person involved and date occurred");
        if (!data.Any(p => p.Key.StartsWith("type.", StringComparison.Ordinal) && p.Value == "yes")) missing.Add("Incident type");
        return missing;
    }

    public static string? Validate(IReadOnlyDictionary<string, string>? data)
    {
        if (data is null || data.Any(p => !Keys.Contains(p.Key))) return "The incident form contains an unrecognized field.";
        foreach (var field in Fields)
        {
            var value = data.GetValueOrDefault(field.Key) ?? "";
