using CareConnector.SharedKernel;

namespace CareConnector.Modules.ServiceDelivery.Domain;

/// <summary>Why a resident is being watched more closely for a while. The list is what staff wrote "alert charting" notes about.</summary>
internal enum MonitoringReason
{
    HospitalReturn,
    ReturnedAfterLeaving,
    NewAdmission,
    BehaviorChange,
    ConditionChange,
    FallOrInjury,
    MedicationChange,
    Other,
}

/// <summary>
/// A monitoring period: one check each shift for a set number of days after an event. It is an ordinary line on the
/// service plan, so the checks appear on the roster and in rounds, are recorded with the same rules as any service,
/// and stop by themselves on the last day.
/// </summary>
internal static class Monitoring
{
    public const string ServiceCode = "MONITORING";

    public const string Source = "Monitoring";

    /// <summary>Monitoring checks are on every staff group's roster.</summary>
    public const string EveryGroup = "Everyone";

    public static readonly IReadOnlyList<int> Lengths = [2, 3, 7, 14];

    private static readonly Dictionary<MonitoringReason, string> Labels = new()
    {
        [MonitoringReason.HospitalReturn] = "Back from hospital or emergency room",
        [MonitoringReason.ReturnedAfterLeaving] = "Back after leaving without notice",
        [MonitoringReason.NewAdmission] = "New admission",
        [MonitoringReason.BehaviorChange] = "Change in behavior",
        [MonitoringReason.ConditionChange] = "Change in condition",
        [MonitoringReason.FallOrInjury] = "Fall or injury",
        [MonitoringReason.MedicationChange] = "Medication change",
        [MonitoringReason.Other] = "Other",
    };

    public static string Label(MonitoringReason reason) => Labels[reason];

    /// <summary>The plan line for a monitoring period starting today: a check two hours into each shift, through the last day.</summary>
    public static Result<PlanItemDetails> Plan(Facility facility, MonitoringReason reason, string? whatToWatch, int days, DateOnly today)
    {
        ArgumentNullException.ThrowIfNull(facility);
        if (!Lengths.Contains(days))
        {
            return new Error("monitoring.length_invalid", $"Monitor for {string.Join(", ", Lengths)} days.");
        }

        if (reason == MonitoringReason.Other && string.IsNullOrWhiteSpace(whatToWatch))
        {
            return new Error("monitoring.reason_required", "Say why the resident is being monitored.");
        }

        var times = facility.ShiftStartHours.Select(h => new TimeOnly((h + 2) % 24, 0)).Order().ToList();
        var instructions = string.IsNullOrWhiteSpace(whatToWatch) ? Label(reason) : $"{Label(reason)}. {whatToWatch.Trim()}";
        return new PlanItemDetails(
            ServiceCode, "Monitoring check", ServiceCategory.HealthMonitoring, instructions, null, EveryGroup, times, ServiceDays.None, false, [],
            today, today.AddDays(days), Source);
    }
}

using CareConnector.Modules.Consent.Contracts;
using CareConnector.Modules.ServiceDelivery.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.ServiceDelivery.Domain;

/// <summary>When a scheduled service may be documented, and whether a late entry must say why.</summary>
/// <param name="RequireLateReason">Off by default: lateness is always recorded in minutes, and a reason is welcome but not demanded.</param>
internal sealed record DeliveryWindow(TimeSpan OpensBefore, TimeSpan LateAfter, TimeSpan ClosesAfter, bool RequireLateReason = false)
{
    /// <summary>Working default until each facility sets its own: open 2 hours early, late after 1 hour, closed after 24 hours.</summary>
    public static DeliveryWindow Default { get; } = new(TimeSpan.FromHours(2), TimeSpan.FromMinutes(60), TimeSpan.FromHours(24));
}

/// <summary>What a tablet says about a tap it held while it had no connection.</summary>
/// <param name="Key">The tablet's key for the tap; the same key is recorded once however often it is sent.</param>
/// <param name="Held">How long the tap waited on the tablet before it reached the server, by the tablet's own count.</param>
internal sealed record DeviceTap(Guid? Key, TimeSpan Held)
{
    /// <summary>
    /// A wait shorter than this is ordinary: the few seconds a tap stays on the tablet so it can be undone, plus
    /// network delay. It is not called out on the record. The time is still corrected.
    /// </summary>
    public static readonly TimeSpan Live = TimeSpan.FromSeconds(20);

    /// <summary>A tap held longer than this is not recorded automatically: a person decides what the record should say.</summary>
    public static readonly TimeSpan MaxHeld = TimeSpan.FromHours(12);

    /// <summary>
    /// The moment of the tap: the server's clock less the time the tap waited on the tablet, however short the wait.
    /// (A threshold here once left records up to 30 seconds late; the fleet simulation caught it.)
    /// </summary>
    public static Result<DateTimeOffset> TappedAt(DeviceTap? tap, DateTimeOffset receivedAt)
    {
        if (tap is null || tap.Held <= TimeSpan.Zero)
        {
            return receivedAt;
        }

        if (tap.Held > MaxHeld)
        {
            return new Error("service.held_too_long", "This was tapped more than 12 hours before the tablet could send it. Tell your supervisor so it can be recorded properly.");
        }

        return receivedAt - tap.Held;
    }
}

internal sealed record DeliveryInput(
    DeliveryOutcome Outcome, string? Note, string? LateReason, IReadOnlyDictionary<Measurement, decimal>? Measurements);

/// <summary>
/// One documented delivery (or refusal, or miss) of a service to a resident. The time is the server's clock at the
/// moment staff recorded it: it cannot be typed in, back-dated, or recorded before the service is due. A tablet
/// that was out of Wi-Fi reports only how long the tap waited on the device; the server takes that off its own
/// clock, so the device's clock is never trusted and the wait is on the record. Immutable; corrected by marking it
/// entered in error and recording again.
/// </summary>
internal sealed class ServiceDelivery : AggregateRoot
{
    private ServiceDelivery()
    {
    }

    public Guid ClientId { get; private set; }

    public string FacilityId { get; private set; } = "";

    /// <summary>The plan line delivered; null for an unscheduled service.</summary>
    public Guid? PlanItemId { get; private set; }

    public string ServiceCode { get; private set; } = "";

    public string ServiceName { get; private set; } = "";

    public ServiceCategory Category { get; private set; }

    public string Group { get; private set; } = "";

    /// <summary>The scheduled time this delivery answers; null for PRN and unscheduled services.</summary>
    public DateTimeOffset? ScheduledFor { get; private set; }

    public DeliveryOutcome Outcome { get; private set; }

    public string? Note { get; private set; }

    public DateTimeOffset RecordedAt { get; private set; }

    /// <summary>When the server received it, if the tap waited on the tablet first; null when recorded live.</summary>
    public DateTimeOffset? SyncedAt { get; private set; }

    /// <summary>The tablet's own key for this tap, so sending it twice records it once.</summary>
    public Guid? ClientKey { get; private set; }

    public int MinutesLate { get; private set; }

    public string? LateReason { get; private set; }

    /// <summary>Recorded values as <c>Name=value;Name=value</c>.</summary>
    public string Measurements { get; private set; } = "";

    public string RecordedBy { get; private set; } = "";

    public string RecordedByName { get; private set; } = "";

    public DeliveryStatus Status { get; private set; }

    public string? EnteredInErrorReason { get; private set; }

    public SensitivityLabel Label { get; private set; }

    public bool WasDelivered => Outcome is DeliveryOutcome.Completed or DeliveryOutcome.CompletedWithPrompting;

    /// <summary>Records a scheduled service from the plan against one of its scheduled times.</summary>
    public static Result<ServiceDelivery> RecordScheduled(
        ServicePlanItem item, string facilityId, DateTimeOffset scheduledFor, DeliveryInput input, DeliveryWindow window,
        SensitivityLabel label, ICurrentUser user, DateTimeOffset now, DeviceTap? tap = null)
    {
        ArgumentNullException.ThrowIfNull(item);
        ArgumentNullException.ThrowIfNull(input);
        ArgumentNullException.ThrowIfNull(window);

        var received = now;
        var tapped = DeviceTap.TappedAt(tap, now);
        if (!tapped.IsSuccess)
        {
            return tapped.Error!;
        }

        now = tapped.Value;

        if (now < scheduledFor - window.OpensBefore)
        {
            return new Error("service.too_early", $"This service is not due yet. It can be recorded from {window.OpensBefore.TotalMinutes:0} minutes before its scheduled time.");
        }

        if (now > scheduledFor + window.ClosesAfter)
        {
            return new Error("service.window_closed", "This service's time has passed. It stays on the record as not documented; tell your supervisor if it was delivered.");
        }

        var late = now > scheduledFor + window.LateAfter;
        if (late && window.RequireLateReason && string.IsNullOrWhiteSpace(input.LateReason))
        {
            return new Error("service.late_reason_required", "This is being recorded late. Say why.");
        }

        // The record carries the canonical service, so every facility's records and reports use one name for one thing.
        var delivery = Create(item.ClientId, facilityId, item.Id, item.CanonicalCode, item.CanonicalName, item.CanonicalCategory, item.Group, scheduledFor, input, item.RequiredMeasurements, label, user, now);
        if (delivery.IsSuccess)
        {
            delivery.Value.Stamp(tap, now, received);
        }

        if (delivery.IsSuccess && late)
        {
            delivery.Value.MinutesLate = (int)(now - scheduledFor).TotalMinutes;
            delivery.Value.LateReason = string.IsNullOrWhiteSpace(input.LateReason) ? null : input.LateReason.Trim();
        }

        return delivery;
    }

    /// <summary>Records an as-needed service from the plan, or a service that is not on the plan at all.</summary>
    public static Result<ServiceDelivery> RecordUnscheduled(
        Guid clientId, string facilityId, ServicePlanItem? prnItem, string serviceCode, string serviceName, ServiceCategory category, string group,
        DeliveryInput input, SensitivityLabel label, ICurrentUser user, DateTimeOffset now, DeviceTap? tap = null)
    {
        ArgumentNullException.ThrowIfNull(input);
        if (string.IsNullOrWhiteSpace(serviceName) || string.IsNullOrWhiteSpace(serviceCode))
        {
            return new Error("service.name_required", "Choose the service.");
        }

        var tapped = DeviceTap.TappedAt(tap, now);
        if (!tapped.IsSuccess)
        {
            return tapped.Error!;
        }

        var delivery = Create(clientId, facilityId, prnItem?.Id, serviceCode.Trim(), serviceName.Trim(), category, group, null, input, prnItem?.RequiredMeasurements ?? [], label, user, tapped.Value);
        if (delivery.IsSuccess)
        {
            delivery.Value.Stamp(tap, tapped.Value, now);
        }

        return delivery;
    }

    private void Stamp(DeviceTap? tap, DateTimeOffset tappedAt, DateTimeOffset receivedAt)
    {
        ClientKey = tap?.Key;
        SyncedAt = receivedAt - tappedAt >= DeviceTap.Live ? receivedAt : null;
    }

    public Result MarkEnteredInError(string reason, ICurrentUser user)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (Status == DeliveryStatus.EnteredInError)
        {
            return Error.Conflict("service.already_entered_in_error", "Already marked entered in error.");
        }

        if (user.UserId != RecordedBy && !user.IsInRole(Roles.Supervisor))
        {
            return new Error("service.correction_forbidden", "Only the person who recorded it or a supervisor can correct it.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("service.reason_required", "A reason is required.");
        }

        Status = DeliveryStatus.EnteredInError;
        EnteredInErrorReason = reason.Trim();
        return Result.Success();
    }

    public IReadOnlyDictionary<string, decimal> RecordedMeasurements() =>
        Measurements.Length == 0
            ? new Dictionary<string, decimal>()
            : Measurements.Split(';').Select(p => p.Split('=')).ToDictionary(p => p[0], p => decimal.Parse(p[1], System.Globalization.CultureInfo.InvariantCulture));

    private static Result<ServiceDelivery> Create(
        Guid clientId, string facilityId, Guid? planItemId, string code, string name, ServiceCategory category, string group, DateTimeOffset? scheduledFor,
        DeliveryInput input, IReadOnlyList<Measurement> required, SensitivityLabel label, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Documenting a service") is { } humanError)
        {
            return humanError;
        }

        if (input.Outcome == DeliveryOutcome.NotDone && string.IsNullOrWhiteSpace(input.Note))
        {
            return new Error("service.note_required", "Say why the service was not done.");
        }

        var values = input.Measurements ?? new Dictionary<Measurement, decimal>();
        var delivered = input.Outcome is DeliveryOutcome.Completed or DeliveryOutcome.CompletedWithPrompting;
        if (delivered && required.FirstOrDefault(m => !values.ContainsKey(m)) is var missing && required.Any(m => !values.ContainsKey(m)))
        {
            return new Error("service.measurement_required", $"Record {Humanize(missing)} with this service.");
        }

        if (values.Any(v => v.Value < 0))
        {
            return new Error("service.measurement_invalid", "A recorded value cannot be negative.");
        }

        var delivery = new ServiceDelivery
        {
            ClientId = clientId,
            FacilityId = facilityId,
            PlanItemId = planItemId,
            ServiceCode = code,
            ServiceName = name,
            Category = category,
            Group = group,
            ScheduledFor = scheduledFor,
            Outcome = input.Outcome,
            Note = string.IsNullOrWhiteSpace(input.Note) ? null : input.Note.Trim(),
            RecordedAt = now,
            Measurements = string.Join(";", values.OrderBy(v => v.Key).Select(v => $"{v.Key}={v.Value.ToString(System.Globalization.CultureInfo.InvariantCulture)}")),
            RecordedBy = user.UserId,
            RecordedByName = user.DisplayName,
            Status = DeliveryStatus.Final,
            Label = label,
        };

        delivery.Raise(new ServiceDocumented(delivery.Id, clientId, facilityId, code, input.Outcome.ToString(), scheduledFor, now));
        return delivery;
    }

    private static string Humanize(Measurement m) =>
        string.Concat(m.ToString().Select((ch, i) => i > 0 && char.IsUpper(ch) ? " " + char.ToLowerInvariant(ch) : ch.ToString().ToLowerInvariant()));
}

using CareConnector.Modules.Consent.Contracts;
using CareConnector.SharedKernel;

namespace CareConnector.Modules.ServiceDelivery.Domain;

/// <summary>How an appointment turned out. Only appointments have one.</summary>
internal enum AppointmentOutcome
{
    Attended,
    Missed,
    Cancelled,
    Rescheduled,
}

/// <param name="With">Who it was with: the agency, the relative, the clinic, the doctor.</param>
/// <param name="Summary">What happened or what was said.</param>
/// <param name="NextStep">What happens next, and who does it.</param>
/// <param name="FollowUpOn">A date to come back to it, if there is one.</param>
internal sealed record EventInput(string ServiceCode, string? With, string? Summary, string? NextStep, DateOnly? FollowUpOn, AppointmentOutcome? Outcome);

/// <summary>
/// A short record of something that happened for a resident and is not a scheduled task: a call with an agency or
/// family, a court date, a benefits matter, an appointment, a message from a physician, labs, an update from a
/// hospital. Three things every time: who, what, and what next. In the previous system these were free-text notes.
/// Immutable once recorded; corrected by marking it entered in error and recording again.
/// </summary>
internal sealed class ServiceEvent : AggregateRoot
{
    /// <summary>The services on the canonical list that are recorded this way.</summary>
    public static readonly IReadOnlyList<string> Codes =
        ["AGENCY", "FAMILY", "COURT", "BENEFITS", "APPOINTMENT", "APPOINTMENT-FOLLOWUP", "PSYCH-VISIT", "MD-CONTACT", "LABS", "HOSPITAL-UPDATE"];

    private ServiceEvent()
    {
    }

    public Guid ClientId { get; private set; }

    public string FacilityId { get; private set; } = "";

    public string ServiceCode { get; private set; } = "";

    public string ServiceName { get; private set; } = "";

    public ServiceCategory Category { get; private set; }

    public string? With { get; private set; }

    public string Summary { get; private set; } = "";

    public string? NextStep { get; private set; }

    public DateOnly? FollowUpOn { get; private set; }

    public AppointmentOutcome? Outcome { get; private set; }

    /// <summary>When it was recorded: the moment of the tap, by the server's clock.</summary>
    public DateTimeOffset RecordedAt { get; private set; }

    /// <summary>When the server received it, if it waited on a tablet first.</summary>
    public DateTimeOffset? SyncedAt { get; private set; }

    /// <summary>The tablet's own key for this tap, so sending it twice records it once.</summary>
    public Guid? ClientKey { get; private set; }

    public string RecordedBy { get; private set; } = "";

    public string RecordedByName { get; private set; } = "";

    public DeliveryStatus Status { get; private set; }

    public string? EnteredInErrorReason { get; private set; }

    public SensitivityLabel Label { get; private set; }

    public static Result<ServiceEvent> Record(
        Guid clientId, string facilityId, EventInput input, SensitivityLabel label, ICurrentUser user, DateTimeOffset now, DeviceTap? tap = null)
    {
        ArgumentNullException.ThrowIfNull(input);
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Recording an event") is { } humanError)
        {
            return humanError;
        }

        if (!Codes.Contains(input.ServiceCode, StringComparer.OrdinalIgnoreCase) || ServiceCatalog.Find(input.ServiceCode) is not { } service)
        {
            return new Error("event.kind_unknown", "Choose what kind of event this is.");
        }

        if (string.IsNullOrWhiteSpace(input.Summary))
        {
            return new Error("event.summary_required", "Say what happened.");
        }

        var appointment = service.Mode == ServiceMode.Appointment;
        if (appointment && input.Outcome is null)
        {
            return new Error("event.outcome_required", "Say whether the appointment was attended, missed, cancelled or rescheduled.");
        }

        if (!appointment && input.Outcome is not null)
        {
            return new Error("event.outcome_not_applicable", "Only an appointment has an outcome.");
        }

        var tapped = DeviceTap.TappedAt(tap, now);
        if (!tapped.IsSuccess)
        {
            return tapped.Error!;
        }

        if (input.FollowUpOn is { } followUp && followUp < DateOnly.FromDateTime(tapped.Value.UtcDateTime).AddDays(-1))
        {
            return new Error("event.follow_up_past", "The follow-up date has already passed.");
        }

        return new ServiceEvent
        {
            ClientId = clientId,
            FacilityId = facilityId,
            ServiceCode = service.Code,
            ServiceName = service.Name,
            Category = service.Category,
            With = Clean(input.With),
            Summary = input.Summary.Trim(),
            NextStep = Clean(input.NextStep),
            FollowUpOn = input.FollowUpOn,
            Outcome = input.Outcome,
            RecordedAt = tapped.Value,
            SyncedAt = now - tapped.Value >= DeviceTap.Live ? now : null,
            ClientKey = tap?.Key,
            RecordedBy = user.UserId,
            RecordedByName = user.DisplayName,
            Status = DeliveryStatus.Final,
            Label = label,
        };
    }

    public Result MarkEnteredInError(string reason, ICurrentUser user)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (Status == DeliveryStatus.EnteredInError)
        {
            return Error.Conflict("event.already_entered_in_error", "Already marked entered in error.");
        }

        if (user.UserId != RecordedBy && !user.IsInRole(Roles.Supervisor))
        {
            return new Error("event.correction_forbidden", "Only the person who recorded it or a supervisor can correct it.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("event.reason_required", "A reason is required.");
        }

        Status = DeliveryStatus.EnteredInError;
        EnteredInErrorReason = reason.Trim();
        return Result.Success();
    }

    private static string? Clean(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}

