/// <param name="Group">Staff group whose roster the service appears on, e.g. <c>MHW1</c>.</param>
/// <param name="ExternalId">Id in the system the item was imported from; makes imports repeatable.</param>
internal sealed record PlanItemDetails(
    string ServiceCode, string ServiceName, ServiceCategory Category, string? Instructions, string? Location, string Group,
    IReadOnlyList<TimeOnly> Times, ServiceDays Days, bool IsPrn, IReadOnlyList<Measurement> Measurements,
    DateOnly EffectiveOn, DateOnly? EndsOn = null, string Source = "CareConnector", string? ExternalId = null);

/// <summary>
/// One service on a resident's service plan: what to do, when, and who does it. A line is never edited or deleted;
/// it is ended (with a reason) and a new line added, so the record shows what the plan said on any day.
/// </summary>
internal sealed class ServicePlanItem : AggregateRoot
{
    private ServicePlanItem()
    {
    }

    public Guid ClientId { get; private set; }

    public string ServiceCode { get; private set; } = "";

    public string ServiceName { get; private set; } = "";

    public ServiceCategory Category { get; private set; }

    public string? Instructions { get; private set; }

    public string? Location { get; private set; }

    public string Group { get; private set; } = "";

    /// <summary>Scheduled local times as <c>HH:mm,HH:mm</c>; empty for as-needed services.</summary>
    public string Times { get; private set; } = "";

    public ServiceDays Days { get; private set; }

    public bool IsPrn { get; private set; }

    /// <summary>Measurements to record with the service, comma-separated <see cref="Measurement"/> names.</summary>
    public string Measurements { get; private set; } = "";

    public DateOnly EffectiveOn { get; private set; }

    public DateOnly? EndsOn { get; private set; }

    public string? EndedReason { get; private set; }

    public bool OnHold { get; private set; }

    public string? HoldReason { get; private set; }

    public string Source { get; private set; } = "";

    public string? ExternalId { get; private set; }

    public string CreatedBy { get; private set; } = "";

    public string CreatedByName { get; private set; } = "";

    public DateTimeOffset CreatedAt { get; private set; }

    public SensitivityLabel Label { get; private set; }

    /// <summary>The canonical service this line stands for, if any. The line itself keeps the name it was given.</summary>
    public CatalogService? Canonical => ServiceCatalog.Match(ServiceCode, ServiceName);

    /// <summary>What staff see and what is recorded: the canonical name when the line maps to one, its own name otherwise.</summary>
    public string CanonicalName => Canonical?.Name ?? ServiceName;

    public string CanonicalCode => Canonical?.Code ?? ServiceCode;

    public ServiceCategory CanonicalCategory => Canonical?.Category ?? Category;

    public IReadOnlyList<TimeOnly> ScheduledTimes => ServiceTimes.FromStored(Times);

    public IReadOnlyList<Measurement> RequiredMeasurements =>
        Measurements.Length == 0 ? [] : Measurements.Split(',').Select(Enum.Parse<Measurement>).ToList();

    public static Result<ServicePlanItem> Add(Guid clientId, PlanItemDetails d, SensitivityLabel label, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(d);
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Changing a service plan") is { } humanError)
        {
            return humanError;
        }

        if (string.IsNullOrWhiteSpace(d.ServiceName) || string.IsNullOrWhiteSpace(d.ServiceCode))
        {
            return new Error("service.name_required", "Choose the service.");
        }

        if (string.IsNullOrWhiteSpace(d.Group))
        {
            return new Error("service.group_required", "Choose the staff group that delivers this service.");
        }

        if (!d.IsPrn && d.Times.Count == 0)
        {
            return new Error("service.times_required", "A scheduled service needs at least one time of day. Mark it as needed (PRN) if it has no schedule.");
        }

        if (d.IsPrn && d.Times.Count > 0)
        {
            return new Error("service.prn_has_times", "An as-needed (PRN) service has no scheduled times.");
        }

        if (d.EndsOn is { } end && end < d.EffectiveOn)
        {
            return new Error("service.dates_invalid", "The end date is before the start date.");
        }

        return new ServicePlanItem
        {
            ClientId = clientId,
            ServiceCode = d.ServiceCode.Trim(),
            ServiceName = d.ServiceName.Trim(),
            Category = d.Category,
            Instructions = Clean(d.Instructions),
            Location = Clean(d.Location),
            Group = d.Group.Trim(),
            Times = ServiceTimes.Format(d.Times),
            Days = d.Days == ServiceDays.Every ? ServiceDays.None : d.Days,
            IsPrn = d.IsPrn,
            Measurements = string.Join(",", d.Measurements.Distinct().Order()),
            EffectiveOn = d.EffectiveOn,
            EndsOn = d.EndsOn,
            Source = d.Source,
            ExternalId = Clean(d.ExternalId),
            CreatedBy = user.UserId,
            CreatedByName = user.DisplayName,
            CreatedAt = now,
            Label = label,
        };
    }

    /// <summary>Scheduled on this local date: in effect, not on hold, and a scheduled day of the week.</summary>
    public bool IsScheduledOn(DateOnly date) =>
        !IsPrn && !OnHold && IsInEffectOn(date) && Days.Includes(date.DayOfWeek);

    public bool IsInEffectOn(DateOnly date) => date >= EffectiveOn && (EndsOn is null || date <= EndsOn);

    public Result End(DateOnly lastDay, string reason, ICurrentUser user)
    {
        if (ActorRules.RequireHuman(user, "Changing a service plan") is { } humanError)
        {
            return humanError;
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("service.reason_required", "Say why the service is ending.");
        }

        if (EndsOn is not null && EndsOn <= lastDay)
        {
            return Error.Conflict("service.already_ended", "This service has already ended.");
        }

        if (lastDay < EffectiveOn.AddDays(-1))
        {
            return new Error("service.dates_invalid", "The end date is before the start date.");
        }

        EndsOn = lastDay;
        EndedReason = reason.Trim();
        return Result.Success();
    }

    public Result Hold(string reason, ICurrentUser user)
    {
        if (ActorRules.RequireHuman(user, "Changing a service plan") is { } humanError)
        {
            return humanError;
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("service.reason_required", "Say why the service is on hold.");
        }

        OnHold = true;
        HoldReason = reason.Trim();
        return Result.Success();
    }

    public Result Resume(ICurrentUser user)
    {
        if (ActorRules.RequireHuman(user, "Changing a service plan") is { } humanError)
        {
            return humanError;
        }

        OnHold = false;
        HoldReason = null;
        return Result.Success();
    }

    private static string? Clean(string? value) => string.IsNullOrWhiteSpace(value) ? null : value.Trim();
}

using CareConnector.SharedKernel;

namespace CareConnector.Modules.ServiceDelivery.Domain;

internal enum OccurrenceState
{
    /// <summary>Too early to record.</summary>
    Upcoming,

    /// <summary>Inside its window: can be recorded now.</summary>
    Due,

    /// <summary>Past its time and not documented, but still recordable with a reason.</summary>
    Overdue,

    /// <summary>The window closed with nothing documented.</summary>
    NotDocumented,

    Documented,
}

/// <summary>One scheduled time of one plan line, with what (if anything) was documented for it.</summary>
internal sealed record Occurrence(ServicePlanItem Item, DateTimeOffset ScheduledFor, OccurrenceState State, ServiceDelivery? Delivery);

/// <summary>
/// Turns service plans into what is due. Pure and deterministic: the same plan, deliveries and clock always give the
/// same list. Times are the facility's local wall-clock times.
/// </summary>
internal static class ServiceSchedule
{
    /// <summary>Every scheduled occurrence with a scheduled time in [from, to).</summary>
    public static IReadOnlyList<Occurrence> Between(
        IEnumerable<ServicePlanItem> items, IEnumerable<ServiceDelivery> deliveries, Facility facility,
        DateTimeOffset from, DateTimeOffset to, DateTimeOffset now, DeliveryWindow window)
    {
        ArgumentNullException.ThrowIfNull(items);
        ArgumentNullException.ThrowIfNull(deliveries);
        ArgumentNullException.ThrowIfNull(facility);
        ArgumentNullException.ThrowIfNull(window);

        var documented = deliveries
            .Where(d => d.Status == DeliveryStatus.Final && d.PlanItemId is not null && d.ScheduledFor is not null)
            .GroupBy(d => (d.PlanItemId!.Value, d.ScheduledFor!.Value.ToUniversalTime()))
            .ToDictionary(g => g.Key, g => g.OrderBy(d => d.RecordedAt).Last());

        var zone = facility.Zone;
        var result = new List<Occurrence>();
        var firstDay = FacilityClock.LocalDate(facility, from).AddDays(-1);
        var lastDay = FacilityClock.LocalDate(facility, to);
        foreach (var item in items)
        {
            for (var day = firstDay; day <= lastDay; day = day.AddDays(1))
            {
                if (!item.IsScheduledOn(day))
                {
                    continue;
                }

                foreach (var time in item.ScheduledTimes)
                {
                    var at = FacilityClock.At(zone, day, time.Hour, time.Minute);
                    if (at < from || at >= to)
                    {
                        continue;
                    }

                    // A time that was already late when the line was added was never expected of anyone.
                    if (at + window.LateAfter < item.CreatedAt)
                    {
                        continue;
                    }

                    documented.TryGetValue((item.Id, at.ToUniversalTime()), out var delivery);
                    result.Add(new Occurrence(item, at, StateOf(at, delivery, now, window), delivery));
                }
            }
        }

        return result.OrderBy(o => o.ScheduledFor).ThenBy(o => o.Item.ServiceName, StringComparer.Ordinal).ToList();
    }

    public static OccurrenceState StateOf(DateTimeOffset scheduledFor, ServiceDelivery? delivery, DateTimeOffset now, DeliveryWindow window)
    {
        ArgumentNullException.ThrowIfNull(window);
        if (delivery is not null)
        {
            return OccurrenceState.Documented;
        }

        if (now < scheduledFor - window.OpensBefore)
        {
            return OccurrenceState.Upcoming;
        }

        if (now <= scheduledFor + window.LateAfter)
        {
            return OccurrenceState.Due;
        }

        return now <= scheduledFor + window.ClosesAfter ? OccurrenceState.Overdue : OccurrenceState.NotDocumented;
    }
}

