/// <summary>Times of day in the forms staff and the legacy system write them: "6:30AM, 10AM, 1PM", "06:30", "13:00".</summary>
internal static class ServiceTimes
{
    private static readonly string[] Formats = ["h:mmtt", "htt", "h:mm tt", "h tt", "H:mm", "HH:mm", "HHmm"];

    public static Result<IReadOnlyList<TimeOnly>> Parse(string? text)
    {
        if (string.IsNullOrWhiteSpace(text))
        {
            return Result<IReadOnlyList<TimeOnly>>.Success([]);
        }

        var times = new List<TimeOnly>();
        foreach (var part in text.Split([',', ';', '|'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries))
        {
            if (!TimeOnly.TryParseExact(part.ToUpperInvariant(), Formats, CultureInfo.InvariantCulture, DateTimeStyles.None, out var time))
            {
                return new Error("service.time_invalid", $"\"{part}\" is not a time of day. Use forms like 6:30AM or 13:00.");
            }

            times.Add(time);
        }

        return Result<IReadOnlyList<TimeOnly>>.Success(times.Distinct().Order().ToList());
    }

    public static string Format(IEnumerable<TimeOnly> times) => string.Join(",", times.Order().Select(t => t.ToString("HH:mm", CultureInfo.InvariantCulture)));

    public static IReadOnlyList<TimeOnly> FromStored(string stored) =>
        stored.Length == 0 ? [] : stored.Split(',').Select(t => TimeOnly.ParseExact(t, "HH:mm", CultureInfo.InvariantCulture)).ToList();
}

