/// <summary>CareConnector access, independent of imported scheduling records and Microsoft directory administration.</summary>
internal sealed class AccessGrant : AggregateRoot
{
    private AccessGrant() { }
    public string UserId { get; private set; } = "";
    public string DisplayName { get; private set; } = "";
    public string Roles { get; private set; } = "";
    public string Facilities { get; private set; } = "";
    public Guid? StaffMemberId { get; private set; }
    public bool Enabled { get; private set; }
    public int Revision { get; private set; }
    public string Reason { get; private set; } = "";
    public string ChangedBy { get; private set; } = "";
    public DateTimeOffset ChangedAt { get; private set; }

    internal static readonly string[] KnownRoles = [SharedKernel.Roles.Clinician, SharedKernel.Roles.DirectCare, SharedKernel.Roles.Supervisor, SharedKernel.Roles.FrontDesk, SharedKernel.Roles.Administrator];

    public static Result<AccessGrant> Create(string userId, string name, IReadOnlyList<string> roles, IReadOnlyList<string> facilities,
        Guid? staffMemberId, string reason, ICurrentUser actor, DateTimeOffset now)
    {
        if (!Guid.TryParse(userId, out var id)) return new Error("access.identity", "Enter the Microsoft account object ID.");
        var grant = new AccessGrant { UserId = id.ToString() };
        var result = grant.Change(name, roles, facilities, staffMemberId, true, 0, reason, actor, now);
        return result.IsSuccess ? grant : result.Error!;
    }

    public Result Change(string name, IReadOnlyList<string> roles, IReadOnlyList<string> facilities, Guid? staffMemberId,
        bool enabled, int revision, string reason, ICurrentUser actor, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(actor);
        if (ActorRules.RequireHuman(actor, "Changing staff access") is { } human) return human;
        if (Revision != revision) return new Error("access.changed", "Access changed while you were editing. Reload and try again.", ErrorKind.Conflict);
        if (string.IsNullOrWhiteSpace(name) || name.Length > 200) return new Error("access.name", "Enter a name of up to 200 characters.");
        if (string.IsNullOrWhiteSpace(reason) || reason.Length > 500) return new Error("access.reason", "Give a reason of up to 500 characters.");
        if (roles.Count == 0 || roles.Any(r => !KnownRoles.Contains(r, StringComparer.Ordinal))) return new Error("access.roles", "Choose at least one AlamoPOC role.");
        if (facilities.Count == 0 || facilities.Any(f => !FacilityDirectory.Known.Any(k => k.Id == f))) return new Error("access.facilities", "Choose at least one known facility.");
        DisplayName = name.Trim();
        Roles = string.Join(',', roles.Distinct().Order(StringComparer.Ordinal));
        Facilities = string.Join(',', facilities.Distinct().Order(StringComparer.Ordinal));
        StaffMemberId = staffMemberId;
        Enabled = enabled;
        Revision++;
        Reason = reason.Trim();
        ChangedBy = actor.UserId;
        ChangedAt = now;
        Raise(new Contracts.StaffAccessChanged(UserId, Revision, Enabled, now));
        return Result.Success();
    }
}

/// <summary>Append-only access decision history, committed with the grant and its audit entries.</summary>
internal sealed class AccessChange : AggregateRoot
{
    private AccessChange() { }
    public string UserId { get; private set; } = "";
    public int Revision { get; private set; }
    public string Roles { get; private set; } = "";
