    public string Reason { get; private set; } = "";
    public string ChangedBy { get; private set; } = "";
    public string ChangedByName { get; private set; } = "";
    public DateTimeOffset ChangedAt { get; private set; }
    public static AccessChange From(AccessGrant grant, ICurrentUser actor) => new()
    {
        UserId = grant.UserId, Revision = grant.Revision, Roles = grant.Roles, Facilities = grant.Facilities,
        StaffMemberId = grant.StaffMemberId, Enabled = grant.Enabled, Reason = grant.Reason,
        ChangedBy = actor.UserId, ChangedByName = actor.DisplayName, ChangedAt = grant.ChangedAt,
    };
}

