namespace CareConnector.Modules.Tablets.Domain;

/// <summary>
/// One of the shared tablets. It is set up once by a supervisor, belongs to a facility, and can be revoked if it is
/// lost: from that moment nothing it sends is accepted, whoever's key signed it.
/// </summary>
internal sealed class Tablet : AggregateRoot
{
    private Tablet()
    {
    }

    public string Name { get; private set; } = "";

    public string FacilityId { get; private set; } = "";

    public string EnrolledBy { get; private set; } = "";

    public string EnrolledByName { get; private set; } = "";

    public DateTimeOffset EnrolledAt { get; private set; }

    public DateTimeOffset? RevokedAt { get; private set; }

    public string? RevokedByName { get; private set; }

    public string? RevokedReason { get; private set; }

    /// <summary>When the server last accepted a signed request from it. Not a clinical fact: updated without an audit row.</summary>
    public DateTimeOffset? LastSeenAt { get; private set; }

    public bool IsRevoked => RevokedAt is not null;

    public static Result<Tablet> Enrol(string name, Facility? facility, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (ActorRules.RequireHuman(user, "Setting up a tablet") is { } humanError)
        {
            return humanError;
        }

        if (!user.IsInRole(Roles.Supervisor) && !user.IsInRole(Roles.Administrator))
        {
            return new Error("tablet.setup_forbidden", "A supervisor sets up a tablet.", ErrorKind.Forbidden);
        }

        if (string.IsNullOrWhiteSpace(name) || name.Trim().Length > 40)
        {
            return new Error("tablet.name_required", "Give the tablet a name of up to 40 characters.");
        }

        if (facility is null)
        {
            return new Error("tablet.facility_required", "Choose the tablet's facility.");
        }

        return new Tablet { Name = name.Trim(), FacilityId = facility.Id, EnrolledBy = user.UserId, EnrolledByName = user.DisplayName, EnrolledAt = now };
    }

    public Result Revoke(string reason, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (!user.IsInRole(Roles.Supervisor) && !user.IsInRole(Roles.Administrator))
        {
            return new Error("tablet.revoke_forbidden", "A supervisor revokes a tablet.", ErrorKind.Forbidden);
        }

        if (IsRevoked)
        {
            return Error.Conflict("tablet.already_revoked", "This tablet is already revoked.");
        }

        if (string.IsNullOrWhiteSpace(reason))
        {
            return new Error("tablet.reason_required", "Say why the tablet is being revoked.");
        }

        RevokedAt = now;
        RevokedByName = user.DisplayName;
        RevokedReason = reason.Trim();
        return Result.Success();
    }
}

/// <summary>
/// One person's signing key on one tablet. The public half is here; the private half stays on the tablet, locked by
/// that person's PIN. The roles are the ones the person held when they added themselves, so a tap signed while the
/// tablet was out of contact is judged by what they were allowed to do then.
/// </summary>
internal sealed class StaffKey : AggregateRoot
{
    private StaffKey()
    {
    }

    public Guid TabletId { get; private set; }

    public string UserId { get; private set; } = "";

    public string DisplayName { get; private set; } = "";

    /// <summary>Comma-separated role names.</summary>
    public string Roles { get; private set; } = "";

    /// <summary>The public key, as base64 SubjectPublicKeyInfo (ECDSA P-256).</summary>
    public string PublicKey { get; private set; } = "";

    public DateTimeOffset CreatedAt { get; private set; }

    public DateTimeOffset? RevokedAt { get; private set; }

    public static Result<StaffKey> Register(Tablet tablet, string publicKey, IReadOnlyCollection<string> roles, ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(tablet);
        ArgumentNullException.ThrowIfNull(user);
        ArgumentNullException.ThrowIfNull(roles);
        if (ActorRules.RequireHuman(user, "Adding yourself to a tablet") is { } humanError)
        {
            return humanError;
        }

        if (tablet.IsRevoked)
        {
            return Error.Conflict("tablet.revoked", "This tablet has been revoked.");
        }

        try
        {
            using var key = System.Security.Cryptography.ECDsa.Create();
            key.ImportSubjectPublicKeyInfo(Convert.FromBase64String(publicKey ?? ""), out _);
            if (key.KeySize != 256)
            {
                return new Error("tablet.key_invalid", "The tablet sent a key of the wrong kind.");
            }
        }
        catch (Exception ex) when (ex is FormatException or System.Security.Cryptography.CryptographicException)
        {
            return new Error("tablet.key_invalid", "The tablet sent a key that cannot be read.");
        }

        return new StaffKey
        {
            TabletId = tablet.Id,
            UserId = user.UserId,
            DisplayName = user.DisplayName,
            Roles = string.Join(",", roles),
            PublicKey = publicKey!,
            CreatedAt = now,
        };
    }

    /// <summary>The person, or a supervisor, withdraws the key: a forgotten PIN, or someone who has left.</summary>
    public Result Revoke(ICurrentUser user, DateTimeOffset now)
    {
        ArgumentNullException.ThrowIfNull(user);
        if (user.UserId != UserId && !user.IsInRole(SharedKernel.Roles.Supervisor) && !user.IsInRole(SharedKernel.Roles.Administrator))
        {
            return new Error("tablet.key_revoke_forbidden", "Only the person or a supervisor can withdraw a key.", ErrorKind.Forbidden);
        }

        RevokedAt ??= now;
        return Result.Success();
    }
}

