/// <summary>Only typed presentation/procedure preferences; no free text, resident data or authority.</summary>
internal sealed class EmployeeProfile : AggregateRoot
{
    private EmployeeProfile() { }
    public string EmployeeKey { get; private set; } = "";
    public string TextSize { get; private set; } = "standard";
    public string Spacing { get; private set; } = "comfortable";
    public string Guidance { get; private set; } = "expanded";
    public int Revision { get; private set; }
    public int SchemaVersion { get; private set; } = 1;
    public DateTimeOffset UpdatedAt { get; private set; }

    public static EmployeeProfile For(EmployeeContext employee) => new() { EmployeeKey = employee.Key };
    public Result Change(EmployeeContext employee, WorkspacePreferences preferences, int revision, DateTimeOffset now)
    {
        if (EmployeeKey != employee.Key) return new Error("workspace.owner", "These preferences belong to another employee.", ErrorKind.Forbidden);
        if (revision != Revision) return Error.Conflict("workspace.changed", "Your preferences changed on another device. Reload before saving.");
        if (preferences.TextSize is not ("standard" or "large") || preferences.Spacing is not ("comfortable" or "spacious") || preferences.Guidance is not ("expanded" or "compact"))
            return new Error("workspace.preference", "Choose one of the supported display and guidance options.");
        TextSize = preferences.TextSize; Spacing = preferences.Spacing; Guidance = preferences.Guidance;
        Revision++; UpdatedAt = now;
        return Result.Success();
    }
    public WorkspaceProfile Describe() => new(new(TextSize, Spacing, Guidance), Revision, UpdatedAt);
}

