/// <summary>Employee-confirmed working area, not a staffing assignment or an authorization grant.</summary>
internal sealed class FloorCoverage : AggregateRoot
{
    private FloorCoverage() { }
    public string EmployeeKey { get; private set; } = "";
    public string FacilityId { get; private set; } = "";
    public DateTimeOffset ShiftStart { get; private set; }
    public string Group { get; private set; } = "";
    public string RoomsJson { get; private set; } = "[]";
    public int AccessRevision { get; private set; }
    public int Revision { get; private set; }
    public Guid RequestId { get; private set; }
    public string RequestHash { get; private set; } = "";
    public DateTimeOffset ConfirmedAt { get; private set; }
    public string[] Rooms() => JsonSerializer.Deserialize<string[]>(RoomsJson) ?? [];
    public static FloorCoverage For(EmployeeContext employee, string facility) => new() { EmployeeKey = employee.Key, FacilityId = facility };
    public Result Confirm(EmployeeContext employee, DateTimeOffset shift, string group, string[] rooms, int revision, Guid request, string hash, DateTimeOffset now)
    {
        if (employee.Key != EmployeeKey || !employee.FacilityIds.Contains(FacilityId)) return new Error("floor.owner", "This working area belongs to another employee.", ErrorKind.Forbidden);
        if (revision != Revision) return Error.Conflict("floor.changed", "Your working area changed. Reload before confirming.");
        if (request == Guid.Empty || string.IsNullOrWhiteSpace(group) || group.Length > 100 || rooms.Length > 500 || rooms.Any(r => string.IsNullOrWhiteSpace(r) || r.Length > 200))
            return new Error("floor.coverage", "Choose a working area and valid rooms.");
        ShiftStart = shift; Group = group; RoomsJson = JsonSerializer.Serialize(rooms.Distinct().Order(StringComparer.Ordinal));
        AccessRevision = employee.AccessRevision; Revision++; RequestId = request; RequestHash = hash; ConfirmedAt = now;
        return Result.Success();
    }
}

/// <summary>A durable personal reminder. Reviewing it never changes any service outcome.</summary>
internal sealed class CareReturn : AggregateRoot
{
    private CareReturn() { }
    public string EmployeeKey { get; private set; } = "";
    public string FacilityId { get; private set; } = "";
    public Guid ClientId { get; private set; }
    public string ReferencesJson { get; private set; } = "[]";
    public string RequestHash { get; private set; } = "";
    public DateTimeOffset AddedAt { get; private set; }
    public DateTimeOffset? ReviewedAt { get; private set; }
    public Guid? ReviewRequestId { get; private set; }
    public int Revision { get; private set; }
    public CareReturnReference[] References() => JsonSerializer.Deserialize<CareReturnReference[]>(ReferencesJson) ?? [];
    public static Result<CareReturn> Add(EmployeeContext employee, string facility, Guid client, CareReturnReference[] items, Guid request, string hash, DateTimeOffset now)
    {
        if (!employee.FacilityIds.Contains(facility)) return new Error("floor.facility", "Choose an available facility.", ErrorKind.Forbidden);
        if (request == Guid.Empty || client == Guid.Empty || items.Length is < 1 or > 10 || items.Any(i => i.PlanItemId == Guid.Empty))
            return new Error("floor.return", "Choose the resident and scheduled care to return to.");
        return new CareReturn { Id = request, EmployeeKey = employee.Key, FacilityId = facility, ClientId = client,
            ReferencesJson = JsonSerializer.Serialize(items), RequestHash = hash, AddedAt = now };
    }
    public Result Review(EmployeeContext employee, int revision, Guid request, DateTimeOffset now)
    {
        if (employee.Key != EmployeeKey || !employee.FacilityIds.Contains(FacilityId)) return new Error("floor.owner", "This reminder belongs to another employee.", ErrorKind.Forbidden);
        if (request == Guid.Empty) return new Error("floor.request", "Use a request ID.");
        if (ReviewRequestId == request) return Result.Success();
        if (revision != Revision || ReviewedAt is not null) return Error.Conflict("floor.changed", "This reminder changed. Reload before reviewing.");
        ReviewedAt = now; ReviewRequestId = request; Revision++; return Result.Success();
    }
}

