/// <summary>Operational ownership, never a substitute for the incident's clinical confirmation.</summary>
internal sealed class IncidentFollowUp : AggregateRoot
{
    private IncidentFollowUp() { }
    public string TenantId { get; private set; } = "";
    public Guid IncidentId { get; private set; }
    public Guid ClientId { get; private set; }
    public string FacilityId { get; private set; } = "";
    public string Kind { get; private set; } = "";
    public string Instruction { get; private set; } = "";
    public string AssigneeId { get; private set; } = "";
    public string AssigneeName { get; private set; } = "";
    public DateTimeOffset DueAt { get; private set; }
    public string Status { get; private set; } = "Assigned";
    public int Revision { get; private set; }
    public DateTimeOffset UpdatedAt { get; private set; }
    public bool IsOpen => Status is "Assigned" or "Acknowledged";
    public static bool Reviewer(EmployeeContext actor) => actor.Roles.Any(r => r is Roles.Supervisor or Roles.Clinician);
    public static string Tenant(EmployeeContext actor) => actor.Key.Split(':')[0];
    public static bool Eligible(StaffAccess target, IncidentWorkflowSnapshot report, string kind) =>
        target.Enabled && (!report.AuthorOnly || target.UserId == report.UploadedBy) && target.FacilityIds.Contains(report.FacilityId, StringComparer.Ordinal) &&
        (target.Roles.Any(r => r is Roles.Supervisor or Roles.Clinician) ||
         (kind == "ProvideInformation" && target.UserId == report.UploadedBy && target.Roles.Contains(Roles.DirectCare)));

    public static Result<IncidentFollowUp> Create(EmployeeContext actor, IncidentWorkflowSnapshot report, string kind,
        string instruction, StaffAccess target, DateTimeOffset dueAt, DateTimeOffset now)
    {
        if (!Reviewer(actor) || !actor.FacilityIds.Contains(report.FacilityId)) return Denied();
        if (report.Status is not ("NeedsReview" or "NeedsTranscription")) return ClosedReport();
        if (kind is not ("ProvideInformation" or "ReviewReport")) return new Error("followup.kind", "Choose information follow-up or report review.");
        if (string.IsNullOrWhiteSpace(instruction) || instruction.Length > 1000) return new Error("followup.instruction", "Describe the work in up to 1,000 characters.");
        if (!Eligible(target, report, kind)) return new Error("followup.assignee", "Choose an enabled employee who can do this work at this facility.");
        if (!ValidDue(dueAt, now)) return InvalidDue();
        return new IncidentFollowUp { TenantId = Tenant(actor), IncidentId = report.Id, ClientId = report.ClientId,
            FacilityId = report.FacilityId, Kind = kind, Instruction = instruction.Trim(), AssigneeId = target.UserId,
            AssigneeName = target.DisplayName, DueAt = dueAt.ToUniversalTime(), Revision = 1, UpdatedAt = now };
    }

    public Result Act(string action, EmployeeContext actor, IncidentWorkflowSnapshot report, int revision,
        string note, StaffAccess? target, DateTimeOffset? dueAt, DateTimeOffset now)
    {
        if (IncidentId != report.Id || ClientId != report.ClientId || FacilityId != report.FacilityId) return Denied();
        if (TenantId != Tenant(actor) || !actor.FacilityIds.Contains(FacilityId) || !IncidentSkill.Available(actor)) return Denied();
        if (revision != Revision) return Error.Conflict("followup.changed", "This follow-up changed. Reload before acting.");
        if (!IsOpen) return Error.Conflict("followup.closed", "This follow-up is already closed. Its history is retained.");
        if (note.Length > 1000) return new Error("followup.note", "Use up to 1,000 characters.");
        var owner = actor.UserId == AssigneeId;
        if (action == "cancel")
        {
            if (!Reviewer(actor)) return Denied();
            if (string.IsNullOrWhiteSpace(note)) return new Error("followup.reason", "Explain why this follow-up is being cancelled.");
            Status = "Cancelled";
        }
        else
        {
            if (report.Status == "EnteredInError") return ClosedReport();
            switch (action)
            {
                case "assign":
                    if (!Reviewer(actor)) return Denied();
                    if (string.IsNullOrWhiteSpace(note)) return new Error("followup.reason", "Explain the reassignment or due-date change.");
                    if (target is null || !Eligible(target, report, Kind)) return new Error("followup.assignee", "This employee can no longer do this work.");
                    if (dueAt is null || !ValidDue(dueAt.Value, now)) return InvalidDue();
                    AssigneeId = target.UserId; AssigneeName = target.DisplayName; DueAt = dueAt.Value.ToUniversalTime(); Status = "Assigned";
                    break;
                case "acknowledge":
                    if (!owner) return Denied();
                    if (Status != "Assigned") return Error.Conflict("followup.acknowledged", "You already acknowledged this assignment.");
                    Status = "Acknowledged";
                    break;
                case "complete":
                    if (!owner) return Denied();
                    if (Status != "Acknowledged") return new Error("followup.acknowledge", "Acknowledge the assignment before completing it.");
                    if (string.IsNullOrWhiteSpace(note)) return new Error("followup.outcome", "Record what you completed for the reviewer.");
                    if (Kind == "ReviewReport" && report.Status != "Confirmed") return new Error("followup.confirm", "Confirm the incident through its review before completing this review assignment.");
                    Status = "Completed";
                    break;
                default: return new Error("followup.action", "Choose a supported follow-up action.");
            }
        }
        Revision++; UpdatedAt = now;
        return Result.Success();
    }

    private static bool ValidDue(DateTimeOffset due, DateTimeOffset now) => due > now && due <= now.AddYears(1);
    private static Error InvalidDue() => new("followup.due", "Choose a future due date within one year. This is a work assignment, not a regulatory deadline.");
    private static Error Denied() => new("followup.denied", "Your current access does not allow this action.", ErrorKind.Forbidden);
    private static Error ClosedReport() => Error.Conflict("followup.report_closed", "The incident is closed to this action. A reviewer can cancel outstanding work with a reason.");
}

