namespace CareConnector.Modules.Workflows.Domain;

internal static class IncidentSkill
{
    public const string Workflow = "incident-review";
    public const string Version = "2";
    public const string WorkflowVersion = "1";
    public const string Id = "incident-completeness";
    // Change this revision whenever handler semantics change; release requires WorkflowHarnessTests and the API matrix.
    private const string Handler = "saved-required-fields-source-v2";
    public static readonly SkillManifest Manifest = new(Id, Version, Workflow, WorkflowVersion, "Incident review companion", Handler,
        ["incident.read", "incident.check-saved"], "WorkflowHarnessTests", Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(
            $"{Id}|{Version}|{Workflow}|{WorkflowVersion}|{Handler}|incident.read,incident.check-saved|WorkflowHarnessTests"))));

    public static bool Available(EmployeeContext employee) => employee.Roles.Any(r => r is Roles.DirectCare or Roles.Clinician or Roles.Supervisor);

    public static Result<IncidentGuidance> Evaluate(EmployeeContext employee, IncidentWorkflowSnapshot report)
    {
        if (!Available(employee) || !employee.FacilityIds.Contains(report.FacilityId, StringComparer.Ordinal))
            return new Error("workflow.denied", "This workflow is outside your current access.", ErrorKind.Forbidden);
        if (report.Status is not ("NeedsReview" or "NeedsTranscription" or "Confirmed" or "EnteredInError"))
            return Error.Conflict("workflow.state", "This report state is not supported by the published workflow.");
        var terminal = report.Status is "Confirmed" or "EnteredInError";
        var reviewer = employee.Roles.Any(r => r is Roles.Clinician or Roles.Supervisor);
        var canEdit = report.CanEdit && (report.UploadedBy == employee.UserId || reviewer);
        var canConfirm = report.CanConfirm && reviewer && !terminal;
        var stage = terminal ? report.Status : report.Missing.Count > 0 ? "NeedsInformation" : canConfirm ? "ReadyForReview" : "AwaitingReviewer";
        return new IncidentGuidance(Workflow, WorkflowVersion, report.Id, report.Revision, stage,
        [
            new("original", report.HasOriginal ? "Original received" : "Initial statement saved", "complete", report.HasOriginal ? "The uploaded original is preserved. Check its resident link before confirmation." : "The first saved statement and later revisions are preserved. Check the resident link and reported facts before confirmation."),
            new("review", "Review all five sections", report.Status == "Confirmed" ? "complete" : report.Status == "EnteredInError" ? "closed" : "current", report.HasOriginal ? "Compare every section with the original. Missing-field checks cannot establish that the facts are correct." : "Check the reported facts in every section. Missing-field checks cannot establish that the facts are correct."),
            new("confirm", "Human confirmation", report.Status == "Confirmed" ? "complete" : report.Status == "EnteredInError" ? "closed" : "pending", "A clinician or supervisor checks the source and resident link, then confirms through the report's review action.")
        ],
        [
            new("incident.read", report.HasOriginal ? "Read report and original" : "Read report and saved statement", true, "Your current role and clinical access allow this record."),
            new("incident.check-saved", "Check saved report", true, "Checks required fields in the saved revision; makes no changes to the report."),
            new("incident.edit", "Save review draft", canEdit && !terminal, terminal ? "The report is closed to editing." : canEdit ? "You are the uploader or an authorized reviewer." : "Only the uploader or a clinician or supervisor may edit."),
            new("incident.confirm", "Confirm report", canConfirm, terminal ? "The report is closed to confirmation." : canConfirm ? "Your personal attestation is required in the report." : "A clinician or supervisor must confirm.")
        ], report.Missing);
    }

    public static string EvidenceHash(IncidentGuidance guidance) => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(guidance))));
}

