/// <summary>A receipt for reviewing references. It never changes the referenced care or its owner.</summary>
internal sealed class ShiftHandoff : AggregateRoot
{
    private ShiftHandoff() { }
    public string TenantId { get; private set; } = "";
    public string FacilityId { get; private set; } = "";
    public DateTimeOffset ShiftStart { get; private set; }
    public DateTimeOffset ShiftEnd { get; private set; }
    public string SenderId { get; private set; } = "";
    public string SenderName { get; private set; } = "";
    public string RecipientId { get; private set; } = "";
    public string RecipientName { get; private set; } = "";
    public string ReferencesJson { get; private set; } = "[]";
    public string Status { get; private set; } = "Sent";
    public int Revision { get; private set; } = 1;
    public DateTimeOffset SentAt { get; private set; }
    public DateTimeOffset? AcknowledgedAt { get; private set; }
    public DateTimeOffset? WithdrawnAt { get; private set; }
    public IReadOnlyList<ShiftWorkRef> References() => JsonSerializer.Deserialize<ShiftWorkRef[]>(ReferencesJson)!;
    public bool IsCarryForward => SenderId == RecipientId;

    public static Result<ShiftHandoff> Send(EmployeeContext actor, string facility, ShiftWindow shift, string recipientId,
        string recipientName, IReadOnlyList<ShiftWorkRef> references, DateTimeOffset now)
    {
        if (!IncidentSkill.Available(actor) || !actor.FacilityIds.Contains(facility)) return Denied();
        if (!Guid.TryParse(recipientId, out _) || references.Count is < 1 or > 50 || references.Distinct().Count() != references.Count)
            return new Error("handoff.items", "Choose 1 to 50 different work items and an enabled recipient.");
        if (now < shift.Start || now >= shift.End) return Error.Conflict("handoff.shift_changed", "The shift changed. Refresh My Shift before sending.");
        if (references.Any(r => r.Id == Guid.Empty || r.Kind is not ("services" or "documents" or "followups") ||
            (r.Kind == "services" ? r.ShiftStart != shift.Start || r.Group?.Length > 100 : r.ShiftStart is not null || r.Group is not null)))
            return new Error("handoff.reference", "Choose work from the current shift workspace.");
        return new ShiftHandoff { TenantId = IncidentFollowUp.Tenant(actor), FacilityId = facility,
            ShiftStart = shift.Start, ShiftEnd = shift.End, SenderId = actor.UserId, SenderName = actor.DisplayName,
            RecipientId = recipientId, RecipientName = recipientName, ReferencesJson = JsonSerializer.Serialize(references), SentAt = now };
    }

    public Result Act(string action, EmployeeContext actor, int revision, DateTimeOffset now)
    {
        if (TenantId != IncidentFollowUp.Tenant(actor) || !actor.FacilityIds.Contains(FacilityId) || !IncidentSkill.Available(actor)) return Denied();
        if (revision != Revision || Status != "Sent") return Error.Conflict("handoff.changed", "This handoff changed. Reload before acting.");
        switch (action)
        {
            case "acknowledge":
                if (actor.UserId != RecipientId) return Denied();
                if (IsCarryForward && now < ShiftEnd) return new Error("handoff.next_shift", "Carry-forward work can be acknowledged after this shift ends.");
                Status = "Acknowledged"; AcknowledgedAt = now;
                break;
            case "withdraw":
                if (actor.UserId != SenderId) return Denied();
                Status = "Withdrawn"; WithdrawnAt = now;
                break;
            default: return new Error("handoff.action", "Choose acknowledge or withdraw.");
        }
        Revision++;
        return Result.Success();
    }

    private static Error Denied() => new("handoff.denied", "Your current access does not allow this action.", ErrorKind.Forbidden);
}

