using CareConnector.SharedKernel;

namespace CareConnector.Modules.Workflows.Domain;

/// <summary>Unattested selections, retained for recovery only. Never dispatched as clinical commands.</summary>
internal sealed class WorkContinuationDraft : AggregateRoot
{
    private WorkContinuationDraft() { }
    public string EmployeeKey { get; private set; } = "";
    public string FacilityId { get; private set; } = "";
    public string ScopeKey { get; private set; } = "";
    public string PayloadJson { get; private set; } = "";
    public int Revision { get; private set; }
    public Guid RequestId { get; private set; }
    public DateTimeOffset SavedAt { get; private set; }
    public static WorkContinuationDraft For(string employee, string facility, string scope) => new() { EmployeeKey = employee, FacilityId = facility, ScopeKey = scope };
    public Result Save(string employee, SaveContinuation request, DateTimeOffset now)
    {
        if (EmployeeKey != employee || FacilityId != request.Facility || ScopeKey != request.Snapshot.StorageKey) return new Error("continuation.owner", "These selections belong to another workspace.", ErrorKind.Forbidden);
        var json = request.Snapshot.Serialize();
        if (RequestId == request.RequestId) return PayloadJson == json ? Result.Success() : Error.Conflict("continuation.reused", "This request ID was already used for other selections.");
        if (Revision != request.Revision) return Error.Conflict("continuation.changed", "Saved selections changed on another screen. Reload before continuing.");
        PayloadJson = json; RequestId = request.RequestId; Revision++; SavedAt = now;
        return Result.Success();
    }
}
